//! The property patches — `set_video`, `set_audio`, `set_text`, `set_shape`
//! and, for the clip's own name and label, `set_clip` (spec §6, the "Clips"
//! table). The range checks that police everything written into a clip's
//! property groups are `props_check.rs`'s, cut out of here in phase 2;
//! this file runs them after every merge and restates none of them.
//!
//! This is the schema half of editing, split off from `edit_clip.rs`'s
//! placement half: nothing here moves a clip in time or on a track, and
//! nothing here decides what a clip IS. It answers one question — is this
//! patch a legal description of this group, and what does the group look
//! like once it is merged in?
//!
//! Three things run through all of it:
//!
//! 1. **A patch is a subset of one group**, read by `patch.rs`'s
//!    [`merge_group`] — the walk of keys and JSON kinds against the group's
//!    template, the deep merge and the typed read back, so a field is
//!    patchable the moment `model.rs` declares it and there is no second
//!    list of patchable keys to forget to update. That module was cut out
//!    of this one under the size rule, and it holds every sentence about
//!    what a patch may CARRY; nothing here restates them.
//! 2. **A mistake is named, never dropped.** A typed Swift builder and an
//!    MCP call both reach these ops, and a key silently dropped here is a
//!    bug the user would never see.
//! 3. **Values are named, never clamped.** A channel outside 0–1 is a units
//!    mistake (0–255) and a scale of 50 is a typo; silently clamping them
//!    would leave the user looking at a number the inspector did not
//!    accept. The one deliberate exception is `set_speed`, which lives in
//!    `edit_clip.rs` and clamps because a slider asking for ×20 wants the
//!    fastest thing available.
//!
//! The bounds themselves, and the four checks against them, are
//! `props_check.rs`'s (the inspector's numbers, spec §4.3): a value that
//! passes there is a value a control can show, and a merge here is stored
//! only once its group has passed. Exactly one check stays behind —
//! [`check_blend`], which refuses a blend mode on a nest clip — because it
//! is a fact about the CLIP and not about the vocabulary, and nothing in
//! `props_check.rs` is handed a clip to ask.

use serde_json::Value;

use crate::edit_adjustment::{check_adjustment_video, check_qualifier_clip};
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::export::describe;
use crate::lut::normalise_look;
use crate::model::{BlendMode, Clip, Project, Source, TextProps, VideoProps};
use crate::outcome::Outcome;
use crate::patch::{merge_group, Group, GROUPS};
use crate::props_check::{check_audio, check_shape, check_text, check_video};

/// The one check a video group cannot make on its own: a NEST clip may not
/// carry a blend mode (format version 6).
///
/// A nest is FLATTENED rather than composited offscreen (`nest.rs`), so
/// there is no such thing as "the nest's picture" for a blend to combine
/// with what is under it — each clip inside contributes its own layer, and a
/// blend on the nest clip could only mean "blend every one of them
/// separately against whatever happens to be below". That is a different
/// picture from the one the popup promises, and a wrong picture is worse
/// than a refusal.
///
/// **Only a non-normal MERGED value fires**, which is not leniency for its
/// own sake. `paste_attributes` replaces the video group WHOLE, so a check
/// on any MENTION of the key would fail an all-or-nothing paste of an
/// ordinary look — one that never touched blend — onto a nest clip, for a
/// value that changes nothing. `{"blend": "normal"}` on a nest clip is
/// therefore the identity and answers [`Outcome::Identity`] through the
/// usual `finish`.
///
/// It lives HERE rather than in `props_check.rs` because it is not a fact
/// about the vocabulary: the value is perfectly legal and it is the CLIP it
/// was written onto that refuses it, where `props_check.rs` never sees a
/// clip. Both callers — the patch path and every pasted video group — run
/// it inside [`Project::settle_video`], so the two give the identical message.
///
/// It is not the whole story either: `set_action_end` checks the VOCABULARY
/// and never the clip, and a blend mode is a legal value, so an end patch
/// can still carry one onto a nest clip. `actions_clamp.rs`'s `clamp_video` is
/// what closes that door, for the recipe, `clip_state` and both export
/// writers at once.
fn check_blend(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if props.blend != BlendMode::Normal && matches!(clip.source, Source::Nest { .. }) {
        return Err(format!(
            "clip {} shows a nest and cannot take a blend mode",
            clip.id
        ));
    }
    Ok(())
}

/// `set_audio`'s one refusal of a legal value (spec §11 AU-111).
const NEEDS_SPEECH: &str =
    "audio.duck.mode speech needs the clip's media to carry speech spans (set_media_speech)";

/// Whether the PATCH itself sets `duck.mode` to `speech` — read from the
/// patch and never from the merged props, so a clip already holding a
/// spanless speech duck (Paste Attributes makes one) keeps every other
/// audio edit (spec §11 AU-111).
fn sets_speech_duck(patch: &Value) -> bool {
    patch.pointer("/duck/mode").and_then(Value::as_str) == Some("speech")
}

// ---- the ops -------------------------------------------------------------

impl Project {
    /// Merges `patch` into every named clip's video props (spec §6).
    /// An identity when nothing changes; `Err` for an unknown clip, a clip
    /// with no video props, an unknown key, or a value out of range.
    pub fn set_video(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Video)
    }

    /// Merges `patch` into every named clip's audio props (spec §6). A patch
    /// setting `duck.mode` to `speech` is refused on a clip that is not a
    /// media clip or whose media has no `speech` (spec §11 AU-111).
    pub fn set_audio(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Audio)
    }

    /// Whether `clip` is a media clip whose media carries `speech`.
    fn has_speech(&self, clip: &Clip) -> bool {
        let Source::Media { media, .. } = clip.source else {
            return false;
        };
        self.media(media).is_some_and(|m| m.speech.is_some())
    }

    /// Merges `patch` into every named text clip's text props (spec §6).
    pub fn set_text(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Text)
    }

    /// Merges `patch` into every named shape clip's shape props (spec §6).
    pub fn set_shape(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Shape)
    }

    /// Sets or clears every named clip's own name and label (spec §6) — the
    /// fifth patch op, shaped like `set_video` so that "absent keeps, null
    /// clears" lives where it already does in this crate: inside a patch
    /// object, never as an `Option<T>` envelope argument, where absent and
    /// null decode alike. The keys are `name` and `label`, each a string or `null`.
    /// A string is stored trimmed, and an EMPTY one — after trimming — clears
    /// too: `set_track`'s rule for a name, except that "unnamed" is `None`
    /// here, so the app's fallback name returns. `Err` for an unknown clip,
    /// an unknown key, or a value that is neither a string nor `null`;
    /// an identity when nothing changes.
    pub fn set_clip(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        let Some(fields) = patch.as_object() else {
            return Err(format!(
                "clip patch must be a json object, not {}",
                describe(patch)
            ));
        };
        // The outer `Option` is "was the key given"; the inner is what to
        // store, `None` for a clear.
        let mut name: Option<Option<String>> = None;
        let mut label: Option<Option<String>> = None;
        for (key, value) in fields {
            let slot = match key.as_str() {
                "name" => &mut name,
                "label" => &mut label,
                other => return Err(format!("unknown key \"{other}\" in a clip patch")),
            };
            *slot = Some(match value {
                Value::Null => None,
                Value::String(text) => Some(text.trim())
                    .filter(|t| !t.is_empty())
                    .map(String::from),
                other => {
                    return Err(format!(
                        "\"{key}\" in a clip patch must be a string or null, not {}",
                        describe(other)
                    ))
                }
            });
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();

        let mut next = self.clone();
        for id in ids {
            if let Some(slot) = next.clip_mut(id) {
                if let Some(name) = &name {
                    slot.name = name.clone();
                }
                if let Some(label) = &label {
                    slot.label = label.clone();
                }
            }
        }
        self.finish(next)
    }

    /// Puts a motion preset's two edge durations and its `during` period on
    /// the document's frame grid — the core's Times rule (core/CLAUDE.md:
    /// every tick value that reaches the model is snapped first) applied at
    /// the patch door, where before D1·2 a comment in `props_check.rs` said
    /// "the inspector snaps" and left an agent's value sub-frame.
    ///
    /// It runs AFTER the range check, so a refusal names the number the
    /// caller actually sent: a `duration` of −1 is a sign mistake and is
    /// refused, where snapping first would have turned it into a legal 0 and
    /// said nothing. Snapping cannot undo that check — a non-negative
    /// duration snaps to a non-negative one — with one exception, and
    /// `period` carries its own floor for it: it divides in every `during`
    /// formula, so a period under half a frame would snap to 0 and stop the
    /// motion the caller asked for. On the grid the smallest period there
    /// is is one frame, so that is where it lands.
    pub(crate) fn snap_motion(&self, props: &mut VideoProps) {
        let Some(motion) = props.motion.as_mut() else {
            return;
        };
        for edge in [motion.r#in.as_mut(), motion.out.as_mut()]
            .into_iter()
            .flatten()
        {
            edge.duration = self.snapped(edge.duration);
        }
        if let Some(during) = motion.during.as_mut() {
            during.period = self.snapped(during.period).max(self.frame());
        }
    }

    /// The same for a text animation's two timings ([`Self::snap_motion`]
    /// argues the order and the rounding). Both are DURATIONS, so 0 is
    /// legal and a reveal shorter than half a frame lands there: it is a
    /// reveal no frame could show.
    ///
    /// It snaps every `text.words[i].start` and `end` too (format version
    /// 9, spec §11's W-3): a word time is a clip time like any other a patch
    /// carries, so it lands on the grid AFTER `check_text` has named what
    /// the caller sent. Nearest, never clamped — a negative start is legal
    /// ("already said") and stays negative. Two words may land on one
    /// frame, which the check allows and the recipe resolves (the later
    /// one wins that frame).
    ///
    /// `pub(crate)` for the one text patch that is not `set_text`:
    /// `add_text_clip`'s, which runs the same merge and the same check in
    /// `edit_clip.rs` and must land on the same grid.
    pub(crate) fn snap_animation(&self, props: &mut TextProps) {
        for word in &mut props.words {
            word.start = self.snapped(word.start);
            word.end = self.snapped(word.end);
        }
        let Some(animation) = props.animation.as_mut() else {
            return;
        };
        animation.r#in = self.snapped(animation.r#in);
        animation.out = self.snapped(animation.out);
    }

    /// The chain that makes a video group storable — `set_video`'s and every
    /// pasted video group's (issue #349), so a group written by hand into a
    /// clipboard payload meets exactly what a patch meets, in the same
    /// order and with the same sentences.
    ///
    /// 1. **One spelling of "no motion"** (format version 8, road map 5
    ///    §5a): a patch that clears the last filled slot leaves a `Motion`
    ///    with three `None`s behind, and a payload's `{"motion": {}}` or
    ///    three explicit nulls deserialise to the same thing; either would
    ///    round-trip as `{"in": null, "out": null, "during": null}` and make
    ///    two equal clips compare unequal. It is normalised HERE rather than
    ///    in serde, because the deep merge is what produces the empty one —
    ///    a caller who writes `{"motion": {}}` means the same thing and gets
    ///    the same answer. The invariant stays open only at the FILE reader,
    ///    which keeps the long spelling on purpose until a patch touches it
    ///    (`core/tests/schema_v8.rs`'s
    ///    `a_motion_whose_slots_are_all_cleared_normalises_back_to_null`;
    ///    road map 7 §2.2).
    /// 2. The vocabulary's ranges (`check_video`), on the values the caller
    ///    sent.
    /// 3. An identity curve is stored as none (spec §11 GR-12), AFTER the
    ///    range check so a malformed identity-shaped curve is still refused
    ///    by name; an identity curve on an uncurved clip is then an identity.
    /// 4. The rules about this CLIP rather than the values — [`check_blend`],
    ///    the adjustment and qualifier rules, the cutout's clip kinds (spec
    ///    §11 CO-20), Behind Subject's (CO-52), motion blur's (CU-111), the
    ///    look's media.
    /// 5. Motion timings snapped to the grid ([`Self::snap_motion`]).
    ///
    /// The look's own normalisation (`normalise_look`) is the patch path's
    /// alone: it reads the PATCH, which a pasted group does not have.
    pub(crate) fn settle_video(&self, clip: &Clip, props: &mut VideoProps) -> Result<(), String> {
        if props.motion.is_some_and(|motion| motion.is_empty()) {
            props.motion = None;
        }
        check_video(props, self.source_size(clip))?;
        props.curves.drop_identities();
        check_blend(clip, props)?;
        check_adjustment_video(clip, props)?;
        check_qualifier_clip(clip, props)?;
        crate::cutout_check::check_cutout_clip(clip, props)?;
        crate::cutout_check::check_behind_subject_clip(clip, props)?;
        crate::motion_blur::check_motion_blur_clip(clip, props)?;
        self.check_hide_silent_clip(clip, props)?;
        self.check_look_media(props)?;
        self.snap_motion(props);
        Ok(())
    }

    /// What `paste_attributes` runs on each group it has just replaced, and
    /// `paste` on every group of every clip it lands
    /// ([`Self::normalise_and_check_pasted`]), so a payload written by hand
    /// meets the bounds a patch does and a group `paste_attributes` did not
    /// touch is not its business. A video group goes through
    /// [`Self::settle_video`], `set_video`'s own chain; the other three
    /// through the same `check_audio` / `check_text` / `check_shape` the
    /// patch path calls, a text group's timings then snapped to the
    /// destination grid. A group the clip lacks has nothing to check.
    pub(crate) fn normalise_and_check_group(
        &self,
        clip: &mut Clip,
        group: Group,
    ) -> Result<(), String> {
        match group {
            Group::Video => {
                if let Some(mut video) = clip.video.clone() {
                    self.settle_video(clip, &mut video)?;
                    clip.video = Some(video);
                }
            }
            Group::Audio => {
                if let Some(audio) = clip.audio.as_ref() {
                    check_audio(audio)?;
                }
            }
            Group::Text => {
                if let Some(text) = clip.text.as_mut() {
                    check_text(text)?;
                    self.snap_animation(text);
                }
            }
            Group::Shape => {
                if let Some(shape) = clip.shape.as_ref() {
                    check_shape(shape)?;
                }
            }
        }
        Ok(())
    }

    /// The clip's speed against `SPEED_MIN`–`SPEED_MAX`, then every group of
    /// one clip `paste` is about to land, through
    /// [`Self::normalise_and_check_group`] in [`GROUPS`] order, so a payload
    /// written by hand meets the bounds a patch does (issue #62, #206). A
    /// failure names the id the PAYLOAD gave the clip, the only one its
    /// writer knows. The callers have already reset a non-finite or
    /// non-positive speed to 1. The clip's own times are the caller's to
    /// re-snap, after this, at the speed checked here.
    pub(crate) fn normalise_and_check_pasted(
        &self,
        clip: &mut Clip,
        payload_id: u32,
    ) -> Result<(), String> {
        // Spelled as JSON spells it, as `validate`'s speed sentence is.
        if !(SPEED_MIN..=SPEED_MAX).contains(&clip.speed) {
            return Err(format!(
                "pasted clip {payload_id}: speed {} is outside ×{SPEED_MIN}–×{SPEED_MAX}",
                serde_json::Value::from(clip.speed)
            ));
        }
        for group in GROUPS {
            self.normalise_and_check_group(clip, group)
                .map_err(|why| format!("pasted clip {payload_id}: {why}"))?;
        }
        Ok(())
    }

    /// The one implementation behind the four `set_*` property ops: merge,
    /// check the keys against the group's schema, deserialize, range-check,
    /// store.
    ///
    /// A clip that does not HAVE the group is an error, not a silent skip:
    /// the group's presence is what "this clip has audio" / "this is a text
    /// clip" means, and inventing it would put text props on a video clip.
    fn patch_clips(&self, clips: &[u32], patch: &Value, group: Group) -> Result<Outcome, String> {
        if !patch.is_object() {
            return Err(format!(
                "{} patch must be a json object, not {}",
                group.name(),
                describe(patch)
            ));
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
        if ids.is_empty() {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in ids {
            let clip = match next.clip(id) {
                Some(clip) => clip.clone(),
                None => continue,
            };
            match group {
                Group::Video => {
                    let base = clip
                        .video
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no video properties"))?;
                    let mut props = merge_group(&base, patch, group)?;
                    normalise_look(&mut props, patch)?;
                    self.settle_video(&clip, &mut props)?;
                    if let Some(slot) = next.clip_mut(id) {
                        slot.video = Some(props);
                    }
                }
                Group::Audio => {
                    let base = clip
                        .audio
                        .ok_or_else(|| format!("clip {id} has no audio properties"))?;
                    let props = merge_group(&base, patch, group)?;
                    check_audio(&props)?;
                    if sets_speech_duck(patch) && !self.has_speech(&clip) {
                        return Ok(Outcome::Refused(NEEDS_SPEECH.to_string()));
                    }
                    if let Some(slot) = next.clip_mut(id) {
                        slot.audio = Some(props);
                    }
                }
                Group::Text => {
                    let base = clip
                        .text
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no text properties"))?;
                    let mut props = merge_group(&base, patch, group)?;
                    check_text(&props)?;
                    self.snap_animation(&mut props);
                    if let Some(slot) = next.clip_mut(id) {
                        slot.text = Some(props);
                    }
                }
                Group::Shape => {
                    let base = clip
                        .shape
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no shape properties"))?;
                    let props = merge_group(&base, patch, group)?;
                    check_shape(&props)?;
                    if let Some(slot) = next.clip_mut(id) {
                        slot.shape = Some(props);
                    }
                }
            }
        }
        self.finish(next)
    }
}

//! things to keep in step in Rust, in `ProjectSnapshot.swift`, in the
//! agent's enum check and in `Compositor.metal`.
//!
//! What is NOT here: the fields that HOLD these values —
//! `VideoProps.spotlight` and `VideoProps.obscure` — which are part of the
//! video group's own shape and stay in `model_props.rs` with it; and every
//! effect that acts on the whole layer rather than a box inside it
//! (filters, chroma key, colour, reflection, shadow), which have no frame
//! to share.
//!
//! # Paths
//!
//! `model_props.rs` re-exports this module whole with
//! `pub use crate::model_regions::*`, and `model.rs` re-exports
//! `model_props.rs` the same way, so `crate::model_props::Spotlight`,
//! `crate::model::Spotlight` and the crate-root re-exports in `lib.rs` all
//! still resolve and no other file needed an import changed. The schema
//! rules are `model.rs`'s too: the field names ARE the JSON keys,
//! declaration order IS key order, every type is `#[serde(default)]` over a
//! hand-written [`Default`] that says what an absent key means, and nothing
//! here carries `deny_unknown_fields`.

use serde::{Deserialize, Serialize};

/// Darkens the canvas outside a rectangle or ellipse, optionally magnifying
/// what is inside it (spec §4.2, M3) — a stand-in for a
/// freehand callout that works on any footage.
///
/// A `video` prop, not a `shape` one, though spec §4.2 first listed it
/// under Shape: the zoom half can only be drawn by the layer that owns the
/// pixels, so it lives beside chroma key, filters and reflection.
///
/// The centre and the box are SOURCE pixels measured from the centre of the
/// layer's cropped rect — the same frame `corner_radius` and `crop` use —
/// so a spotlight stays on the face it was put on when the layer is scaled,
/// moved or rotated.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Spotlight {
    pub shape: SpotShape,
    pub x: f64,
    pub y: f64,
    pub width: f64,
    pub height: f64,
    /// Source pixels the edge is blurred over; 0 is a hard edge.
    pub feather: f64,
    /// How much darker everything OUTSIDE is: 0 changes nothing, 1 is
    /// black.
    pub dim: f64,
    /// Magnification INSIDE the region. 1 is no zoom, which is why the
    /// range starts there and not at 0.
    pub zoom: f64,
}

impl Default for Spotlight {
    /// A 480 × 270 window — a 16:9 quarter of a 1080p source — centred, at
    /// the spec's "darkens the canvas outside" with no zoom.
    fn default() -> Self {
        Spotlight {
            shape: SpotShape::Rect,
            x: 0.0,
            y: 0.0,
            width: 480.0,
            height: 270.0,
            feather: 40.0,
            dim: 0.6,
            zoom: 1.0,
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SpotShape {
    #[default]
    Rect,
    Ellipse,
}

/// The most hidden regions one layer may carry.
///
/// A SHADER BUDGET, exactly as [`crate::model::MAX_FILTERS`] is: the
/// uniform block carries four regions and the fragment stage applies them
/// in a fixed unrolled order, so a fifth has nowhere to go. `set_video`
/// names the overflow rather than dropping it, and the reason is sharper
/// here than it is for a filter — a region the user drew over a face and
/// cannot see is not a control that does nothing, it is the face still on
/// screen.
pub const MAX_OBSCURE: usize = 4;

/// One region of the picture hidden behind a blur or a pixelation (road map
/// 2, phase 3c) — the spotlight's inverse. A face, a password field, a
/// notification that slid in halfway through the take.
///
/// The geometry is [`Spotlight`]'s frame, and the paragraph above that type
/// is its canonical statement: `x`/`y` are the region's CENTRE as an offset
/// in SOURCE pixels from the centre of the layer's cropped rect, `width`
/// and `height` its size in the same pixels. So a region rides with its
/// layer through scale, move and rotation, and stays on the face it was put
/// on. Nothing here is in canvas pixels, and a nest's transform folds into
/// the layer around it rather than into this box.
///
/// `shape` is [`SpotShape`] — the spotlight's own rect/ellipse, reused
/// rather than copied. It is the same vocabulary naming the same distance
/// field, and shared vocabulary has exactly one home (core/CLAUDE.md); if
/// the two ever have to diverge, splitting an enum is a rename, while
/// merging two is a schema migration.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct ObscureRegion {
    pub shape: SpotShape,
    pub x: f64,
    pub y: f64,
    pub width: f64,
    pub height: f64,
    /// Source pixels the effect is ramped in over; 0 is a hard edge.
    pub feather: f64,
    pub kind: ObscureKind,
    /// 0 = the region is there but hides nothing, 1 = its full effect.
    pub amount: f64,
}

impl Default for ObscureRegion {
    /// A 480 × 270 window, centred — [`Spotlight`]'s own default box, so
    /// the two region controls put the SAME rectangle on screen and a user
    /// who has met one recognises the other — pixelated at full strength.
    ///
    /// The kind and the amount are the opposite of
    /// [`crate::model::Filter`]'s half-strength blur, for the opposite
    /// reason. A filter has to be visible without destroying the frame; a
    /// region that only half hides has failed at the one job this feature
    /// has, so its default is the setting that actually hides. Between the
    /// two kinds that is `pixelate`: a blur at the shader's maximum radius
    /// is a SOFT blur — a large password field can still be read through
    /// it — while a pixelation at full strength destroys the detail
    /// outright.
    ///
    /// `feather` is 20 rather than the spotlight's 40 because a region put
    /// over a face is usually much smaller than a callout window, and a
    /// 40-pixel ramp on a 200-pixel box is mostly ramp.
    fn default() -> Self {
        ObscureRegion {
            shape: SpotShape::Rect,
            x: 0.0,
            y: 0.0,
            width: 480.0,
            height: 270.0,
            feather: 20.0,
            kind: ObscureKind::Pixelate,
            amount: 1.0,
        }
    }
}

/// How a region hides what is under it.
///
/// Closed at two, and a type of its own rather than a
/// [`crate::model::FilterKind`] restricted to two of its seven: a range
/// check that had to say "kind must be blur or pixelate" would be a rule
/// about a type enforced a long way from it, which is what `props_check.rs`
/// argues against, and serde would take `"sepia"` out of a hand-written
/// file into a field nothing downstream could repair — there is no neutral
/// obscure kind to fall back to, the way a filter's `amount` can fall back
/// to 0. A closed enum makes the illegal state unrepresentable and hands
/// the shader a two-value discriminant.
///
/// Declaration order is that discriminant's order (`ProjectSnapshot.swift`
/// derives `shaderCode` from the case index and `Compositor.metal` reads
/// the number), so a kind may be added at the END but the two here must
/// never be swapped.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ObscureKind {
    Blur,
    /// The default, and [`ObscureRegion::default`] says why: it is the kind
    /// that actually hides.
    #[default]
    Pixelate,
}
//! The cutout's model vocabulary (format 39, spec §11 CO-20): [`Cutout`], a
//! clip's `video.cutout` — Remove Background, the clip's own layer drawn as
//! its subject alone or whole — with [`CutoutSubject`], [`CutoutQuality`],
//! [`CutoutBackground`] and the ranges `cutout_check.rs` checks and clamps
//! to.
//!
//! Re-exported whole by `model_props.rs` (and so by `model.rs`), so every
//! `crate::model::Cutout` path resolves. What the recipe makes of it is
//! `recipe_layer.rs`'s `layer_cutout` (CO-21). The JSON spelling of each enum
//! variant is persisted: append, never rename.

use serde::{Deserialize, Serialize};

/// `video.cutout.edge`'s range: the outline shrunk (below 0) or grown
/// (above 0) (CO-20).
pub const CUTOUT_EDGE_MIN: f64 = -1.0;
pub const CUTOUT_EDGE_MAX: f64 = 1.0;
/// `video.cutout.feather`'s upper bound; its lower is 0 (CO-20).
pub const CUTOUT_FEATHER_MAX: f64 = 1.0;

/// What the mask finds: a person (CO-1), or, on an image clip only, its
/// foreground (CO10a, format 41, spec §11 CO-100).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CutoutSubject {
    #[default]
    Person,
    Foreground,
}

/// Which masks: Standard, or Best, which waits for S-KEY1's CO-S1 (d) (CO-41).
/// A file's `best` reads; the ops refuse it until Best masks are made (CO-20).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CutoutQuality {
    #[default]
    Standard,
    Best,
}

/// What the layer draws: its subject alone, or whole — the subject still
/// hiding Behind Subject clips (CO-20).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CutoutBackground {
    #[default]
    Remove,
    Keep,
}

/// A clip's `video.cutout` (CO-20), every field written in this order; `{}`
/// reads as the defaults. The key's presence, `subject` and `quality` are
/// the clip's own — the evaluator restores the base over any action's end
/// (`cutout_check.rs`'s `restore_base_cutout`); `edge` and `feather`
/// animate and `background` switches at an action's end.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Cutout {
    pub subject: CutoutSubject,
    pub quality: CutoutQuality,
    pub background: CutoutBackground,
    /// −1…1.
    pub edge: f64,
    /// 0…1.
    pub feather: f64,
}

impl Default for Cutout {
    fn default() -> Self {
        Cutout {
            subject: CutoutSubject::Person,
            quality: CutoutQuality::Standard,
            background: CutoutBackground::Remove,
            edge: 0.0,
            feather: 0.0,
        }
    }
}
//! The cutout's rules on the model (format 39, spec §11 CO-20): the range
//! and quality checks `props_check.rs`'s `check_video` runs on
//! `video.cutout` ([`check_cutout`]); the clip-kind refusal and, since
//! format 41 (spec §11 CO-100), the foreground subject's refusal on a media
//! or still clip, both run by `edit_props.rs`'s `settle_video`, where the
//! clip is known ([`check_cutout_clip`]); the evaluator's clamp `actions_clamp.rs`'s
//! `clamp_video` runs on an action's end ([`clamp_cutout`], which never
//! fails, so the video group always decodes); and [`restore_base_cutout`],
//! `actions.rs`'s statement that the key's presence, `subject` and `quality`
//! are the clip's BASE values, beside motion's. And `video.behind_subject`'s
//! clip-kind refusal (format 40, spec §11 CO-52), run beside the cutout's in
//! `settle_video` ([`check_behind_subject_clip`]). And `video.hide_silent`'s
//! (format 43, spec §11 CO-92): its ranges ([`check_hide_silent`], in
//! `check_video`), its media and the nest refusal
//! ([`Project::check_hide_silent_clip`], in `settle_video`), and the base's
//! gate put back over an action's end beside the cutout's
//! ([`restore_base_video_keys`]).

use serde_json::{Map, Value};

use crate::actions_clamp::bounded;
use crate::evaluate::json;
use crate::model::{
    Clip, Cutout, CutoutQuality, CutoutSubject, HideSilent, Project, Source, VideoProps,
    CUTOUT_EDGE_MAX, CUTOUT_EDGE_MIN, CUTOUT_FEATHER_MAX, HIDE_SILENT_MAX,
};
use crate::props_check::{in_range, ticks_in_range};

/// `video.cutout`'s ranges, each refused in `in_range`'s sentence under its
/// own key, then `best`, which the vocabulary holds and no op may set until
/// Best masks are made (CO-20). No cutout is nothing to check.
pub(crate) fn check_cutout(cutout: &Option<Cutout>) -> Result<(), String> {
    let Some(cutout) = cutout else {
        return Ok(());
    };
    in_range(
        "video.cutout.edge",
        cutout.edge,
        CUTOUT_EDGE_MIN,
        CUTOUT_EDGE_MAX,
    )?;
    in_range(
        "video.cutout.feather",
        cutout.feather,
        0.0,
        CUTOUT_FEATHER_MAX,
    )?;
    if cutout.quality != CutoutQuality::Standard {
        return Err(
            "video.cutout.quality must be standard: Best masks are not made yet".to_string(),
        );
    }
    Ok(())
}

/// A cutout on a clip that cannot take it, refused naming what the clip is
/// (CO-20): a `media`, `still` or `image` clip takes one (CO-100). Then the
/// subject: `foreground` is an image clip's only, and on a `media` or
/// `still` clip it is refused in its own sentence, checked after the kind
/// refusals so every other kind keeps its sentence. Fires only when `props`
/// carries a cutout.
pub(crate) fn check_cutout_clip(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    let Some(cutout) = props.cutout else {
        return Ok(());
    };
    let what = match clip.source {
        Source::Image { .. } => return Ok(()),
        Source::Media { .. } => "a media clip",
        Source::Still { .. } => "a still clip",
        Source::Text => return Err(cannot_take(clip, "a text clip")),
        Source::Shape => return Err(cannot_take(clip, "a shape clip")),
        Source::Graphic => return Err(cannot_take(clip, "a graphic clip")),
        Source::Adjustment => return Err(cannot_take(clip, "an adjustment clip")),
        Source::Nest { .. } => {
            return Err(format!(
                "clip {} shows a nest and cannot take a cutout",
                clip.id
            ))
        }
    };
    if cutout.subject == CutoutSubject::Foreground {
        return Err(format!(
            "clip {} is {what} and cannot take a foreground cutout: only an image clip can",
            clip.id
        ));
    }
    Ok(())
}

/// CO-20's kind refusal, naming what the clip is.
fn cannot_take(clip: &Clip, what: &str) -> String {
    format!("clip {} is {what} and cannot take a cutout", clip.id)
}

/// `video.behind_subject` on a clip that cannot be cut by a subject,
/// refused naming what the clip is (CO-52): an adjustment clip draws no
/// picture of its own, and a nest clip never draws itself (its layers are
/// its contents'). Fires only when the flag is on.
pub(crate) fn check_behind_subject_clip(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if !props.behind_subject {
        return Ok(());
    }
    match clip.source {
        Source::Adjustment => Err(format!(
            "clip {} is an adjustment clip and cannot be put behind a subject",
            clip.id
        )),
        Source::Nest { .. } => Err(format!(
            "clip {} shows a nest and cannot be put behind a subject",
            clip.id
        )),
        _ => Ok(()),
    }
}

/// An evaluated cutout brought into its ranges (CO-20): `edge` to −1…1 and
/// `feather` to 0…1, NaN to 0. Never fails.
pub(crate) fn clamp_cutout(cutout: &mut Option<Cutout>) {
    let Some(cutout) = cutout.as_mut() else {
        return;
    };
    cutout.edge = bounded(cutout.edge, CUTOUT_EDGE_MIN, CUTOUT_EDGE_MAX, 0.0);
    cutout.feather = bounded(cutout.feather, 0.0, CUTOUT_FEATHER_MAX, 0.0);
}

/// The base's cutout put back over the evaluated `video` state (CO-20), at
/// the `Value` level for motion's reason (`actions.rs`): with no base
/// cutout the state's is `null`, whatever an end carried; with one and an
/// object in the state, that object takes the base's `subject` and
/// `quality`, keeping its `edge`, `feather` and `background`; with one and
/// anything else there (an end's hand-written `null`), the base's whole.
pub(crate) fn restore_base_cutout(video: &mut Map<String, Value>, base: Option<&Cutout>) {
    let Some(base) = base else {
        video.insert("cutout".to_string(), Value::Null);
        return;
    };
    match video.get_mut("cutout") {
        Some(Value::Object(state)) => {
            state.insert("subject".to_string(), json(&base.subject));
            state.insert("quality".to_string(), json(&base.quality));
        }
        _ => {
            video.insert("cutout".to_string(), json(base));
        }
    }
}

/// `video.hide_silent`'s three ranges (CO-91), each 0…5 s in
/// `ticks_in_range`'s sentence under its own key. No gate is nothing to
/// check.
pub(crate) fn check_hide_silent(gate: &Option<HideSilent>) -> Result<(), String> {
    let Some(gate) = gate else {
        return Ok(());
    };
    for (key, value) in [
        ("pre_roll", gate.pre_roll),
        ("hold", gate.hold),
        ("fade", gate.fade),
    ] {
        ticks_in_range(
            &format!("video.hide_silent.{key}"),
            value,
            0,
            HIDE_SILENT_MAX,
        )?;
    }
    Ok(())
}

impl Project {
    /// `video.hide_silent` on this clip (CO-92): the media named (0 is not),
    /// in the project, with sound; then a nest clip refused, since it never
    /// draws itself. Fires only when `props` carries a gate.
    pub(crate) fn check_hide_silent_clip(
        &self,
        clip: &Clip,
        props: &VideoProps,
    ) -> Result<(), String> {
        let Some(gate) = props.hide_silent else {
            return Ok(());
        };
        if gate.media == 0 {
            return Err(
                "video.hide_silent.media is required: the media whose speech the clip follows"
                    .to_string(),
            );
        }
        let Some(media) = self.media(gate.media) else {
            return Err(format!(
                "video.hide_silent.media {} is not a media of this project",
                gate.media
            ));
        };
        if !media.has_audio {
            return Err(format!(
                "video.hide_silent.media {} has no sound to follow",
                gate.media
            ));
        }
        if let Source::Nest { .. } = clip.source {
            return Err(format!(
                "clip {} shows a nest and cannot hide while silent: set it on the clips inside",
                clip.id
            ));
        }
        Ok(())
    }
}

/// The base's video keys no action may change, put back over the evaluated
/// state: the cutout's ([`restore_base_cutout`]) and the whole
/// `hide_silent` (CO-92) — the base's, or no key with none.
pub(crate) fn restore_base_video_keys(video: &mut Map<String, Value>, base: &VideoProps) {
    restore_base_cutout(video, base.cutout.as_ref());
    match &base.hide_silent {
        Some(gate) => {
            video.insert("hide_silent".to_string(), json(gate));
        }
        None => {
            video.shift_remove("hide_silent");
        }
    }
}

