//! The cursor's model vocabulary (format 38, spec §11 CU-30, CU-39):
//! [`MediaCursor`], a media's `media.cursor` — the cursor file recorded
//! beside its movie — and [`CursorProps`], a clip's `video.cursor` — how
//! that cursor is drawn — with [`CursorStyle`], [`CursorClicks`] and the
//! ranges `cursor_props.rs` checks and clamps to.
//!
//! Re-exported whole by `model_props.rs` (and so by `model.rs`), so every
//! `crate::model::CursorProps` path resolves. What the recipe makes of the
//! two is `recipe_cursor.rs`'s; reading the file itself is `cursor_track.rs`'s.
//! The JSON spelling of each enum variant is persisted: append, never rename.

use serde::{Deserialize, Serialize};

/// `video.cursor.scale`'s range: the drawn cursor's size against its
/// recorded one (CU-30).
pub const CURSOR_SCALE_MIN: f64 = 0.25;
pub const CURSOR_SCALE_MAX: f64 = 8.0;
/// `video.cursor.hide_idle`'s range, in seconds of no activity (CU-30).
pub const CURSOR_HIDE_IDLE_MIN: f64 = 0.5;
pub const CURSOR_HIDE_IDLE_MAX: f64 = 30.0;
/// `video.cursor.click_size`'s range: a ripple's size against its own (CU-30).
pub const CURSOR_CLICK_SIZE_MIN: f64 = 0.25;
pub const CURSOR_CLICK_SIZE_MAX: f64 = 4.0;
/// A ripple's colour when none is given, and what an unreadable one
/// evaluates as (CU-30).
pub const CURSOR_CLICK_COLOR: &str = "#ffffffcc";

/// A media's cursor file (CU-39): its path, the app's bookmark for it
/// (base64, written only when set) and whether the movie's own picture
/// already shows the pointer, in which case Frame Job draws none (CU-32).
/// `in_picture` is required: a record without it does not read.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MediaCursor {
    pub path: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bookmark: Option<String>,
    pub in_picture: bool,
}

/// Which pointer is drawn: the images the file recorded, or Frame Job's
/// arrow (CU-30).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CursorStyle {
    #[default]
    Recorded,
    Arrow,
}

/// What a click draws: nothing, or a ripple (CU-23, CU-30).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CursorClicks {
    #[default]
    None,
    Ripple,
}

/// A clip's `video.cursor` (CU-30), every field written in this order;
/// `{}` reads as the defaults. `scale` and `click_size` animate in an
/// action; `show`, `style`, `clicks` and `click_color` switch at its end;
/// `smoothing` and `hide_idle` are the clip's own — the recipe reads them
/// from the BASE props only (`cursor_props.rs`'s `with_base_cursor`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct CursorProps {
    pub show: bool,
    pub scale: f64,
    pub style: CursorStyle,
    /// 0…1 (CU-21).
    pub smoothing: f64,
    /// Seconds, 0.5…30, or `None` — never hidden. Written `null`.
    pub hide_idle: Option<f64>,
    pub clicks: CursorClicks,
    /// A CSS colour in G-12's grammar, stored as given.
    pub click_color: String,
    pub click_size: f64,
}

impl Default for CursorProps {
    fn default() -> Self {
        CursorProps {
            show: true,
            scale: 1.0,
            style: CursorStyle::Recorded,
            smoothing: 0.0,
            hide_idle: None,
            clicks: CursorClicks::None,
            click_color: CURSOR_CLICK_COLOR.to_string(),
            click_size: 1.0,
        }
    }
}
//! The cursor's rules on the model (format 38, spec §11 CU-30, CU-39): the
//! range checks `props_check.rs`'s `check_video` runs on `video.cursor`
//! ([`check_cursor`]), the evaluator's clamp `actions_clamp.rs`'s
//! `clamp_video` runs on an action's end ([`clamp_cursor`], which never
//! fails, so the video group always decodes), the media record's check
//! `edit_track.rs`'s `check_media_fields` ends with ([`check_media_cursor`]),
//! and [`with_base_cursor`] — the one statement of "`smoothing` and
//! `hide_idle` are the clip's own", read by the recipe, `split` and
//! `freeze_frame`.

use crate::actions_clamp::bounded;
use crate::model::{
    CursorProps, Media, MediaKind, VideoProps, CURSOR_CLICK_COLOR, CURSOR_CLICK_SIZE_MAX,
    CURSOR_CLICK_SIZE_MIN, CURSOR_HIDE_IDLE_MAX, CURSOR_HIDE_IDLE_MIN, CURSOR_SCALE_MAX,
    CURSOR_SCALE_MIN,
};
use crate::model_color::normalise_color;
use crate::props_check::in_range;

/// `video.cursor`'s ranges, each refused in `in_range`'s sentence under its
/// own key, then the click colour in G-12's grammar (CU-30). No cursor is
/// nothing to check.
pub(crate) fn check_cursor(cursor: &Option<CursorProps>) -> Result<(), String> {
    let Some(cursor) = cursor else {
        return Ok(());
    };
    in_range(
        "video.cursor.scale",
        cursor.scale,
        CURSOR_SCALE_MIN,
        CURSOR_SCALE_MAX,
    )?;
    in_range("video.cursor.smoothing", cursor.smoothing, 0.0, 1.0)?;
    if let Some(hide_idle) = cursor.hide_idle {
        in_range(
            "video.cursor.hide_idle",
            hide_idle,
            CURSOR_HIDE_IDLE_MIN,
            CURSOR_HIDE_IDLE_MAX,
        )?;
    }
    in_range(
        "video.cursor.click_size",
        cursor.click_size,
        CURSOR_CLICK_SIZE_MIN,
        CURSOR_CLICK_SIZE_MAX,
    )?;
    if normalise_color(&cursor.click_color).is_none() {
        return Err(format!(
            "video.cursor.click_color must be a CSS colour (spec §11 G-12), not \"{}\"",
            cursor.click_color
        ));
    }
    Ok(())
}

/// An evaluated cursor brought into its ranges (CU-30): each number clamped,
/// NaN to its default (`hide_idle`'s NaN to none), the click colour
/// normalised and an unreadable one [`CURSOR_CLICK_COLOR`]. Never fails.
pub(crate) fn clamp_cursor(cursor: &mut Option<CursorProps>) {
    let Some(cursor) = cursor.as_mut() else {
        return;
    };
    cursor.scale = bounded(cursor.scale, CURSOR_SCALE_MIN, CURSOR_SCALE_MAX, 1.0);
    cursor.smoothing = bounded(cursor.smoothing, 0.0, 1.0, 0.0);
    cursor.hide_idle = cursor
        .hide_idle
        .filter(|seconds| !seconds.is_nan())
        .map(|seconds| seconds.clamp(CURSOR_HIDE_IDLE_MIN, CURSOR_HIDE_IDLE_MAX));
    cursor.click_size = bounded(
        cursor.click_size,
        CURSOR_CLICK_SIZE_MIN,
        CURSOR_CLICK_SIZE_MAX,
        1.0,
    );
    cursor.click_color =
        normalise_color(&cursor.click_color).unwrap_or_else(|| CURSOR_CLICK_COLOR.to_string());
}

/// A media's `cursor` (CU-39): an empty path refused, and a cursor on
/// anything but a video media with a picture refused naming what it is.
/// The bookmark is stored as given.
pub(crate) fn check_media_cursor(media: &Media) -> Result<(), String> {
    let Some(cursor) = &media.cursor else {
        return Ok(());
    };
    if cursor.path.trim().is_empty() {
        return Err("media cursor path must not be empty".to_string());
    }
    let what = match media.kind {
        MediaKind::Video if media.has_video => return Ok(()),
        MediaKind::Video => "a video media without a picture",
        MediaKind::Audio => "an audio media",
        MediaKind::Image => "an image media",
        MediaKind::Lut => "a LUT media",
    };
    Err(format!(
        "media.cursor needs a video media with a picture, not {what}"
    ))
}

/// `evaluated` with its cursor's `smoothing` and `hide_idle` set to `base`'s
/// — 0 and none when `base` or its cursor is `None` — so neither ever comes
/// from an action's end (CU-30). A `None` evaluated cursor stays `None`.
/// Read by `recipe_cursor.rs`, and by `split`'s second half and
/// `freeze_frame`'s still, so no splitter turns an end's values into a base.
pub(crate) fn with_base_cursor(mut evaluated: VideoProps, base: Option<&VideoProps>) -> VideoProps {
    if let Some(cursor) = evaluated.cursor.as_mut() {
        let base = base.and_then(|video| video.cursor.as_ref());
        cursor.smoothing = base.map_or(0.0, |base| base.smoothing);
        cursor.hide_idle = base.and_then(|base| base.hide_idle);
    }
    evaluated
}
//! The motion vocabulary (format version 8, road map 5's E2): [`Motion`]
//! and the three slots it holds — an entrance ([`MotionEdge`] with an
//! [`EdgeMotion`] kind), an exit (the same pair) and a continuous
//! [`MotionDuring`] with a [`DuringMotion`] kind.
//!
//! **Motion is a preset, not a value.** Every other member of the video
//! group is a quantity the compositor reads more or less straight — an
//! opacity, a scale, four crop edges — while these five types say only what
//! the clip should DO, and the placement that comes out of it is computed
//! by `motion.rs` at render time from the clip's own duration, the
//! container's canvas and the source's size. Nothing here is ever a number
//! the renderer receives: `recipe.rs` publishes no `motion` key at all, and
//! a layer's `scale`, `rotation`, `opacity`, `x` and `y` are where a preset
//! shows up (spec §5.3, §7.3). That is the seam, and it is why these types
//! are their own module rather than five more structs in `model_props.rs`.
//!
//! Re-exported whole by `model_props.rs`, which `model.rs` re-exports whole
//! in turn, so `crate::model::Motion` resolves like every other property
//! type; the FIELD holding it (`VideoProps.motion`) stays with the video
//! group.
//!
//! Neither enum's declaration ORDER is load-bearing — `motion.rs` matches
//! on the variant and nothing crosses to a shader, where
//! [`crate::model::BlendMode`]'s and [`crate::model::ObscureKind`]'s orders
//! are discriminants — so a kind may be added at the END. The JSON spelling
//! of each variant IS persisted, so a rename needs a migration step. Both
//! are closed, so a misspelt kind is refused at the serde boundary rather
//! than clamped later: there is no neutral motion to fall back to, which is
//! [`crate::model::TextAnimationKind`]'s reason exactly. `spin` is spelled
//! in BOTH, which is deliberate and is what the enum sweep in
//! `core/tests/model_tests.rs` reads off the fixture rather than off a
//! list of its own.
//!
//! The rules are `model.rs`'s: the field names ARE the JSON keys,
//! declaration order IS key order, every struct is `#[serde(default)]` over
//! a hand-written [`Default`] that says what an absent key means, and
//! nothing here carries `deny_unknown_fields`.

use serde::{Deserialize, Serialize};

use crate::time::{Ticks, TIMESCALE};

/// What a clip does on its way in, on its way out, and all the way
/// through — three independent slots, each `null` when the clip does
/// nothing of that sort.
///
/// `VideoProps.motion` is `Option<Motion>` rather than this struct with
/// three `None`s, so a clip that does not move writes `"motion": null`
/// instead of three nulls and `{"motion": null}` is an exact clear. A
/// `Motion` whose three slots are all `None` is NORMALISED back to `None`
/// by the patch path (`edit_props.rs`) and by the split rule
/// (`edit_split.rs`), so one clip has one spelling of "no motion" and
/// `is_empty` is the test both use.
///
/// It is NOT an animation target: `set_action_end` refuses a patch naming
/// it, and `evaluate_clip` restores the base value over whatever an action
/// reached, because a preset is anchored to the clip's two ends and an
/// action is a ramp between two states — interpolating "half a slide" into
/// "half a spin" is not a picture anybody asked for (spec §5.4).
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Motion {
    /// The entrance, measured forward from the clip's first frame.
    #[serde(rename = "in")]
    pub r#in: Option<MotionEdge>,
    /// The exit, measured back from the clip's last frame.
    pub out: Option<MotionEdge>,
    /// What the clip does for its whole length, under the two edges.
    pub during: Option<MotionDuring>,
}

impl Motion {
    /// True when no slot is filled — the state that is stored as `None`.
    pub fn is_empty(&self) -> bool {
        self.r#in.is_none() && self.out.is_none() && self.during.is_none()
    }

    /// Every slot filled with its default.
    ///
    /// Not a value any clip is given: this is what `Group::template`
    /// (`edit_props.rs`) hands `check_keys`, which walks a patch against a
    /// fully populated struct to find a misspelt key. Against a `None`
    /// motion there would be nothing to walk INTO, so `{"motion": {"in":
    /// {"durration": 1}}}` would be accepted and silently dropped; with
    /// this, the recursion reaches every level and the refusal names the
    /// dotted path for free.
    pub fn template() -> Motion {
        Motion {
            r#in: Some(MotionEdge::default()),
            out: Some(MotionEdge::default()),
            during: Some(MotionDuring::default()),
        }
    }
}

/// One end of a clip: what it does, and for how long.
///
/// `duration` is a DURATION rather than a time, [`crate::model::TextAnimation`]'s
/// convention — an `in` is measured forward from the clip's first frame and
/// an `out` back from its last — so trimming a clip moves the preset with
/// the edge it belongs to. When `in + out` runs past the clip's own
/// duration the two are scaled down to meet in the middle rather than
/// refused (the tent rule, `motion.rs`), because "too long for THIS clip"
/// is a fact about a clip and not about the vocabulary, and a later trim
/// would invalidate any refusal anyway.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct MotionEdge {
    pub kind: EdgeMotion,
    pub duration: Ticks,
}

impl Default for MotionEdge {
    /// Half a second of [`EdgeMotion::Fade`] — what a caller gets for
    /// naming a slot and saying nothing else.
    ///
    /// The kind is the fade for [`crate::model::Filter::default`]'s reason:
    /// a default must be visibly SOMETHING the moment it is switched on or
    /// the control reads as broken, and of the nine this is the one
    /// everybody can name before they see it. Half a second is that same
    /// test applied to the duration — long enough to read as an entrance
    /// rather than as a cut, short enough that a two-second cutaway is not
    /// still arriving when it is due to leave.
    fn default() -> Self {
        MotionEdge {
            kind: EdgeMotion::Fade,
            duration: TIMESCALE / 2,
        }
    }
}

/// What a clip does for its whole length, under whatever its two edges are
/// doing.
///
/// `amount` is 0–1 and `period` is how long one cycle takes; what each
/// means in pixels or degrees is `motion.rs`'s table, and
/// [`DuringMotion::Drift`] ignores `period` entirely. Both are checked but
/// neither is clamped by the schema: `props_check.rs` refuses an `amount`
/// outside 0–1 and a `period` under one tick on the way in, and `motion.rs`
/// guards them again on the way out, because a hand-written file reaches
/// the renderer without passing an op.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct MotionDuring {
    pub kind: DuringMotion,
    /// 0–1, how much of the preset to apply. 0 is the identity.
    pub amount: f64,
    /// One cycle, in ticks. Ignored by [`DuringMotion::Drift`].
    pub period: Ticks,
}

impl Default for MotionDuring {
    /// A half-strength one-second [`DuringMotion::Pulse`], on
    /// [`MotionEdge::default`]'s terms: the one continuous motion a reader
    /// can name before seeing it, at the middle of its range, over a period
    /// slow enough to read as breathing rather than as a flicker.
    fn default() -> Self {
        MotionDuring {
            kind: DuringMotion::Pulse,
            amount: 0.5,
            period: TIMESCALE,
        }
    }
}

/// The nine entrances and exits of road map 5 §5b.
///
/// One kind, read at an edge: the same variant means the mirrored thing on
/// the way out — `ZoomIn` grows INTO the frame as an entrance and grows
/// away from the viewer as an exit, `SlideLeft` enters from the right edge
/// and leaves past the left one. `motion.rs`'s two tables are the
/// normative statement of every number.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EdgeMotion {
    /// The default, and [`MotionEdge::default`] says why.
    #[default]
    Fade,
    ZoomIn,
    ZoomOut,
    SlideLeft,
    SlideRight,
    SlideUp,
    SlideDown,
    Spin,
    Pop,
}

/// The five continuous motions of road map 5 §5b.
///
/// Every one of them is the identity at clip time 0, so a clip starts
/// exactly where it is placed whatever it goes on to do; `motion.rs`'s
/// table is the normative statement.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DuringMotion {
    /// The default, and [`MotionDuring::default`] says why.
    #[default]
    Pulse,
    Shake,
    /// Spelled in [`EdgeMotion`] too, and deliberately: the same word
    /// means the same thing at an edge and throughout.
    Spin,
    Bounce,
    Drift,
}
//! Motion blur's vocabulary (format 42, spec §11 CU-110…CU-114): the one
//! sample count, `video.motion_blur`'s range check, its clamp, the clips
//! that cannot take it, and the shutter's sub-frame offsets.
//!
//! `video.motion_blur` is the shutter as a fraction of one CANVAS frame,
//! 0…1, 0 off (CU-113). The shutter is centred on the frame's instant: its
//! N samples sit at round(((2k+1−N)/(2N))·s·F) ticks from it, k = 0…N−1
//! ascending, F the canvas's frame in ticks, and its ends at ∓round(s·F/2)
//! (CU-114). One N, [`MOTION_BLUR_SAMPLES`], serves the preview,
//! `render_frame` and every export (CU-112): spike CU-S5 chose it (CU-110).
//! `recipe_blur.rs` turns the offsets into a layer's `blur` key.

use crate::model::{Clip, Source, VideoProps};
use crate::props_check::in_range;
use crate::time::{Fps, Ticks, TIMESCALE};

/// How many sub-frame placements a blurred layer is drawn at (spec §11
/// CU-110: CU-S5's N, the largest of 16, 8 and 4 within its bounds).
pub const MOTION_BLUR_SAMPLES: usize = 16;

/// `video.motion_blur`'s range (CU-113): "video.motion_blur must be between
/// 0 and 1, not 1.5".
pub(crate) fn check_motion_blur(value: f64) -> Result<(), String> {
    in_range("video.motion_blur", value, 0.0, 1.0)
}

/// An evaluated `motion_blur` brought into 0…1, NaN to 0 (an action's end is
/// checked for its keys, not its values). Never fails.
pub(crate) fn clamp_motion_blur(value: f64) -> f64 {
    if value.is_nan() {
        0.0
    } else {
        value.clamp(0.0, 1.0)
    }
}

/// `video.motion_blur` above 0 on a clip that cannot take it, refused naming
/// what the clip is (CU-111): a nest clip never draws itself (its layers are
/// its contents', each with its own blur), and an adjustment clip draws no
/// picture to move. 0 is always accepted.
pub(crate) fn check_motion_blur_clip(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if props.motion_blur <= 0.0 {
        return Ok(());
    }
    match clip.source {
        Source::Nest { .. } => Err(format!(
            "clip {} shows a nest and cannot take motion blur: set it on the clips inside",
            clip.id
        )),
        Source::Adjustment => Err(format!(
            "clip {} is an adjustment clip and cannot take motion blur",
            clip.id
        )),
        _ => Ok(()),
    }
}

/// The shutter's [`MOTION_BLUR_SAMPLES`] centred offsets from the frame's
/// instant, ascending, and its two ends, for a shutter of `shutter` frames at
/// `fps` (CU-114). F = TIMESCALE·den/num as f64; a degenerate rate has no
/// frame, so every offset is 0.
pub(crate) fn shutter_offsets(fps: Fps, shutter: f64) -> (Vec<Ticks>, (Ticks, Ticks)) {
    let frame = if fps.is_valid() {
        TIMESCALE as f64 * f64::from(fps.den) / f64::from(fps.num)
    } else {
        0.0
    };
    let span = shutter * frame;
    let n = MOTION_BLUR_SAMPLES as f64;
    let offsets = (0..MOTION_BLUR_SAMPLES)
        .map(|k| ((2.0 * k as f64 + 1.0 - n) / (2.0 * n) * span).round() as Ticks)
        .collect();
    let half = (span / 2.0).round() as Ticks;
    (offsets, (-half, half))
}
//! Tier 2's range checks (spec §11 GR-11), called from `props_check.rs`'s
//! `check_video`: each wheel's `x`, `y` and `master` −1…1, and its push
//! inside the unit circle; and each curve's 2–16 points, x and y 0…1, x
//! strictly rising (GR-12), a hue curve's x 0 ≤ x < 360 and its value in
//! its domain's range (GR-32); and the qualifier's ranges, each bound in its
//! own sentence and low ≤ high (GR-13), then its `blur` 0…1 (GR-35).
//!
//! The rule is `props_check.rs`'s: a value out of range is NAMED in the
//! rule's own sentence, never clamped (an action's end is clamped instead,
//! by `actions_clamp_grade.rs`'s `clamp_wheels`). The circle test allows
//! [`WHEEL_RIM_TOLERANCE`] past 1, so a rim point made by `cos`/`sin` or
//! divided by its `hypot` — the inspector's puck and `clamp_wheels` both
//! make one — is never refused; the sentence still says `≤ 1`.

use crate::model::{
    CurveDomain, Curves, Qualifier, Wheels, CURVE_POINTS_MAX, CURVE_POINTS_MIN, HUE_SOFTNESS_MAX,
    HUE_TURN, QUALIFIER_BLUR_MAX, WHEEL_MAX, WHEEL_RIM_TOLERANCE,
};
use crate::props_check::in_range;

/// `Ok` when every wheel is in range and inside the circle; the first
/// refusal otherwise, in model order (lift, gamma, gain; x, y, master).
pub(crate) fn check_wheels(wheels: &Wheels) -> Result<(), String> {
    for (name, wheel) in wheels.named() {
        let key = format!("video.wheels.{name}");
        in_range(&format!("{key}.x"), wheel.x, -WHEEL_MAX, WHEEL_MAX)?;
        in_range(&format!("{key}.y"), wheel.y, -WHEEL_MAX, WHEEL_MAX)?;
        in_range(
            &format!("{key}.master"),
            wheel.master,
            -WHEEL_MAX,
            WHEEL_MAX,
        )?;
        if wheel.x * wheel.x + wheel.y * wheel.y > 1.0 + WHEEL_RIM_TOLERANCE {
            return Err(format!(
                "{key} must lie inside the unit circle (x² + y² ≤ 1), not x {}, y {}",
                wheel.x, wheel.y
            ));
        }
    }
    Ok(())
}

/// `Ok` when every curve holds 2–16 points, each x and y 0…1 (bounds
/// inclusive) and x strictly rising; the first refusal otherwise, in model
/// order (master, red, green, blue, hue_hue, hue_sat), then point order,
/// indices 0-based (GR-12). A hue curve's x is 0 ≤ x < 360 and its value
/// within its domain's range (GR-32). An identity curve passes: `set_video`
/// drops it after this.
pub(crate) fn check_curves(curves: &Curves) -> Result<(), String> {
    for (name, domain, curve) in curves.named() {
        let Some(points) = curve else {
            continue;
        };
        let key = format!("video.curves.{name}");
        if !(CURVE_POINTS_MIN..=CURVE_POINTS_MAX).contains(&points.len()) {
            return Err(format!(
                "{key} needs {CURVE_POINTS_MIN} to {CURVE_POINTS_MAX} points, not {}",
                points.len()
            ));
        }
        let (low, high) = domain.value_range();
        for (index, point) in points.iter().enumerate() {
            if domain == CurveDomain::Tone {
                in_range(&format!("{key}[{index}].x"), point[0], 0.0, 1.0)?;
            } else if !(point[0].is_finite() && point[0] >= 0.0 && point[0] < HUE_TURN) {
                return Err(format!(
                    "{key}[{index}].x must be at least 0 and below {HUE_TURN}, not {}",
                    point[0]
                ));
            }
            in_range(&format!("{key}[{index}].y"), point[1], low, high)?;
            if index > 0 && point[0] <= points[index - 1][0] {
                return Err(format!(
                    "{key}[{index}].x ({}) must be greater than {key}[{}].x ({})",
                    point[0],
                    index - 1,
                    points[index - 1][0]
                ));
            }
        }
    }
    Ok(())
}

/// `Ok` when every present range is inside its bounds (all inclusive, spec
/// §11 GR-13): the hue's `center` and `width` 0…360 and its `softness`
/// 0…180; each level range's `low`, `high` and `softness` 0…1 and `low ≤
/// high`. The first refusal otherwise, in the order hue (centre, width,
/// softness), saturation (low, high, softness, then the order), luma the
/// same; then `blur` 0…1 (GR-35), last. A bound is compared exactly, so
/// 360, 180, 0 and 1 all pass.
pub(crate) fn check_qualifier(qualifier: &Qualifier) -> Result<(), String> {
    if let Some(hue) = &qualifier.hue {
        in_range("video.qualifier.hue.center", hue.center, 0.0, HUE_TURN)?;
        in_range("video.qualifier.hue.width", hue.width, 0.0, HUE_TURN)?;
        in_range(
            "video.qualifier.hue.softness",
            hue.softness,
            0.0,
            HUE_SOFTNESS_MAX,
        )?;
    }
    for (name, range) in qualifier.levels() {
        let Some(range) = range else {
            continue;
        };
        let key = format!("video.qualifier.{name}");
        in_range(&format!("{key}.low"), range.low, 0.0, 1.0)?;
        in_range(&format!("{key}.high"), range.high, 0.0, 1.0)?;
        in_range(&format!("{key}.softness"), range.softness, 0.0, 1.0)?;
        if range.low > range.high {
            return Err(format!(
                "{key}.low ({}) must not be greater than {key}.high ({})",
                range.low, range.high
            ));
        }
    }
    in_range(
        "video.qualifier.blur",
        qualifier.blur,
        0.0,
        QUALIFIER_BLUR_MAX,
    )
}

