pub(crate) const MAX_PATCH_DEPTH: u32 = 8;

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Evaluated {
    pub video: VideoProps,
    pub audio: AudioProps,
    pub text: Option<TextProps>,
    pub shape: Option<ShapeProps>,
    pub graphic: Option<GraphicProps>,
    #[serde(skip)]
    pub curve_blends: Vec<CurveBlend>,
}

// ---- curves --------------------------------------------------------------

pub fn ease(curve: Curve, u: f64) -> f64 {
    // NaN would propagate through every interpolated field, so it collapses
    // to the start of the action rather than poisoning the frame.
    let u = if u.is_nan() { 0.0 } else { u.clamp(0.0, 1.0) };
    match curve {
        Curve::Linear => u,
        Curve::EaseIn => u * u,
        // The mirror of ease_in, so an in/out pair is symmetric.
        Curve::EaseOut => 1.0 - (1.0 - u) * (1.0 - u),
        // Smoothstep: zero slope at both ends, which is what "ease in and
        // out" means, in one multiply-add more than the quadratics.
        Curve::EaseInOut => u * u * (3.0 - 2.0 * u),
    }
}

// ---- the two routines ----------------------------------------------------

pub(crate) fn merge(base: &Value, patch: &Value) -> Value {
    merge_at(base, patch, 0)
}

fn merge_at(base: &Value, patch: &Value, depth: u32) -> Value {
    match (base, patch) {
        (Value::Object(b), Value::Object(p)) if depth < MAX_PATCH_DEPTH => {
            let mut out = b.clone();
            for (key, patch_value) in p {
                let merged = match out.get(key) {
                    Some(base_value) => merge_at(base_value, patch_value, depth + 1),
                    None => patch_value.clone(),
                };
                out.insert(key.clone(), merged);
            }
            Value::Object(out)
        }
        _ => patch.clone(),
    }
}

fn lerp(from: &Value, to: &Value, u: f64) -> Value {
    lerp_at(from, to, u, 0)
}

const ENTRY_DISCRIMINANTS: [&str; 2] = ["kind", "shape"];

const OBJECT_DISCRIMINANTS: [&str; 2] = ["kind", "media"];

fn lerp_entry(from: &Value, to: &Value, u: f64, depth: u32) -> Value {
    if let (Value::Object(a), Value::Object(b)) = (from, to) {
        // Both sides must name a discriminant for this to fire, so a patch
        // entry that leaves them out — `{"filters": [{"amount": 1}]}`,
        // "same filter, more of it" — still interpolates, key by key.
        let names_another_thing = ENTRY_DISCRIMINANTS
            .iter()
            .any(|key| matches!((a.get(*key), b.get(*key)), (Some(x), Some(y)) if x != y));
        if names_another_thing {
            return from.clone();
        }
    }
    lerp_at(from, to, u, depth)
}

fn lerp_at(from: &Value, to: &Value, u: f64, depth: u32) -> Value {
    // The two switch points. `u >= 1.0` is what makes non-numeric fields
    // take their new value at the action's end and not one tick earlier.
    if u >= 1.0 {
        return to.clone();
    }
    if u <= 0.0 || depth >= MAX_PATCH_DEPTH {
        return from.clone();
    }
    match (from, to) {
        (Value::Number(a), Value::Number(b)) => lerp_number(a, b, u),
        // Elements go through `lerp_entry`, which is this function under a
        // wider discriminant set — the list rule, stated in full on [`lerp`].
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => Value::Array(
            a.iter()
                .zip(b.iter())
                .map(|(x, y)| lerp_entry(x, y, u, depth + 1))
                .collect(),
        ),
        // A `kind` is a DISCRIMINANT everywhere in §5.2 — a filter's kind,
        // a shape's, a transition's — so two objects that NAME different
        // ones are two different things, and the numbers beside them do not
        // measure the same quantity. Interpolating them would read a blur's
        // strength as a sepia's. The whole object switches at the end
        // instead, exactly as the string naming it would on its own.
        //
        // Both sides must name one for this to fire, so a patch element
        // that leaves `kind` out — `{"filters": [{"amount": 1}]}`, "same
        // filter, more of it" — still interpolates, key by key, below.
        //
        // `kind` and a look's `media` are the discriminants here
        // ([`OBJECT_DISCRIMINANTS`]). A list ENTRY is judged against
        // [`ENTRY_DISCRIMINANTS`] before it ever reaches this arm, and that
        // constant argues why the two sets differ.
        (Value::Object(a), Value::Object(b))
            if OBJECT_DISCRIMINANTS
                .iter()
                .any(|key| matches!((a.get(*key), b.get(*key)), (Some(x), Some(y)) if x != y)) =>
        {
            from.clone()
        }
        (Value::Object(a), Value::Object(b)) => {
            let mut out = Map::new();
            for (key, from_value) in a {
                let value = match b.get(key) {
                    Some(to_value) => lerp_at(from_value, to_value, u, depth + 1),
                    // A key the target lost: nothing to move toward.
                    None => from_value.clone(),
                };
                out.insert(key.clone(), value);
            }
            Value::Object(out)
        }
        _ => from.clone(),
    }
}

fn lerp_number(from: &Number, to: &Number, u: f64) -> Value {
    let (Some(a), Some(b)) = (from.as_f64(), to.as_f64()) else {
        return Value::Number(from.clone());
    };
    let value = a + (b - a) * u;
    if from.is_f64() || to.is_f64() {
        // from_f64 rejects NaN and infinities; falling back to `from` keeps
        // a nonsense patch from turning the whole frame into null.
        Number::from_f64(value)
            .map(Value::Number)
            .unwrap_or_else(|| Value::Number(from.clone()))
    } else {
        // Rust's float-to-int cast saturates, so an absurd patch cannot
        // panic here.
        Value::Number(Number::from(value.round() as i64))
    }
}

// ---- evaluation ----------------------------------------------------------

pub(crate) fn spans(action: &Action, clip_t: Ticks) -> bool {
    action.duration > 0
        && action.start <= clip_t
        && clip_t < action.start.saturating_add(action.duration)
}

pub(crate) fn ordered_actions(clip: &Clip) -> Vec<&Action> {
    let mut actions: Vec<&Action> = clip.actions.iter().collect();
    actions.sort_by_key(|a| (a.start, a.id));
    actions
}

pub(crate) fn to_json<T: Serialize>(value: &T) -> Value {
    serde_json::to_value(value).unwrap_or(Value::Null)
}

pub(crate) fn color_json(color: &ColorAdjust) -> Value {
    let keys = [
        ("brightness", color.brightness),
        ("contrast", color.contrast),
        ("saturation", color.saturation),
        ("hue", color.hue),
        ("exposure", color.exposure),
        ("temperature", color.temperature),
        ("tint", color.tint),
        ("highlights", color.highlights),
        ("shadows", color.shadows),
        ("whites", color.whites),
        ("blacks", color.blacks),
        ("vibrance", color.vibrance),
        ("fade", color.fade),
    ];
    let mut out = Map::new();
    for (key, value) in keys {
        out.insert(key.to_string(), to_json(&value));
    }
    Value::Object(out)
}

pub(crate) fn wheels_json(wheels: &Wheels) -> Value {
    let mut out = Map::new();
    for (name, wheel) in wheels.named() {
        let mut keys = Map::new();
        keys.insert("x".to_string(), to_json(&wheel.x));
        keys.insert("y".to_string(), to_json(&wheel.y));
        keys.insert("master".to_string(), to_json(&wheel.master));
        out.insert(name.to_string(), Value::Object(keys));
    }
    Value::Object(out)
}

pub(crate) fn video_json(video: &VideoProps) -> Value {
    let mut value = to_json(video);
    if let Value::Object(fields) = &mut value {
        fields.insert("color".to_string(), color_json(&video.color));
        fields.insert("wheels".to_string(), wheels_json(&video.wheels));
        fields.insert("curves".to_string(), curves_json(&video.curves));
        if !video.qualifier.is_neutral() {
            fields.insert("qualifier".to_string(), qualifier_json(&video.qualifier));
        }
        // Present at 0, so an end animates from 0 (spec §11 CU-113).
        fields.insert("motion_blur".to_string(), to_json(&video.motion_blur));
    }
    value
}

impl Project {
    pub fn evaluate_clip(&self, clip: &Clip, clip_t: Ticks) -> Evaluated {
        let base_video = clip.video.clone().unwrap_or_default();
        let base_audio = clip.audio.unwrap_or_default();

        let mut fields = Map::new();
        fields.insert("video".to_string(), video_json(&base_video));
        fields.insert("audio".to_string(), audio_json(&base_audio));
        // A patch may only reach `text` on a clip that HAS text: evaluation
        // resolves properties, it never decides what kind of layer a clip
        // is. Leaving the key out makes a stray text patch a no-op.
        if let Some(text) = &clip.text {
            fields.insert("text".to_string(), to_json(text));
        }
        let mut state = Value::Object(fields);

        let actions = ordered_actions(clip);
        // The spanning action's merged target and eased progress, for the
        // curve blends (spec §11 GR-34).
        let mut spanning: Option<(Value, f64)> = None;
        for action in &actions {
            let end = action.start.saturating_add(action.duration);
            if action.duration > 0 && end <= clip_t {
                state = merge(&state, &action.end);
            }
        }
        if let Some(action) = actions.iter().find(|a| spans(a, clip_t)) {
            // Interpolating the WHOLE state toward the patched state, not
            // just the patched keys, is what keeps this to one routine:
            // an untouched field lerps from itself to itself, exactly.
            let mut target = merge(&state, &action.end);
            // An identity curve meeting a curve of another count takes its
            // x's, so a grade animates from (or to) neutral (spec §11 GR-12).
            align_identity_curves(&mut state, &mut target);
            // The hue centre the short way round (spec §11 GR-13).
            align_hue_center(&mut state, &mut target);
            let elapsed = clip_t.saturating_sub(action.start) as f64;
            let progress = elapsed / action.duration as f64;
            let eased = ease(action.curve, progress);
            let mut lerped = lerp(&state, &target, eased);
            // The colours in OKLab from the two ends (spec §11 G-43).
            blend_colors(&state, &target, eased, &mut lerped);
            hold_audio_steps(&state, &mut lerped);
            state = lerped;
            spanning = Some((target, eased));
        }

        // Motion is NOT an animation target (format version 8, spec §5.4).
        // `set_action_end` refuses a patch naming it, but a hand-written
        // file, a pasted action or another tool's project reaches here
        // without passing that op, so the BASE value goes back over what
        // the loop reached — at the `Value` level, since `clamp_video` is
        // never handed the base props and a malformed `motion` would fail the
        // WHOLE video group's decode below, losing every other animated one. The guard is "no input may panic" applied to a value
        // nothing validates: `merge_at` REPLACES on a type mismatch, and
        // `set_action_end` checks only the patch's top level, so
        // `state["video"]` may be a number, string, array, bool or null
        // here — and `IndexMut<&str>` panics on all but null, where it would
        // MINT `{"motion": …}` and decode as DEFAULT props rather than base.
        // With the `if let` each keeps falling through to
        // `.ok().unwrap_or(base_video)`, as it always did.
        //
        // A look that does not read as one becomes no look (spec §11 GR-7),
        // in the same place and for the same reason. `set_action_end` checks
        // an end against the patch TEMPLATE, whose look has a kind, so an end
        // of `{"look": {"amount": 1}}` is accepted — and on a clip with no
        // look (or one whose look was removed after the end was written) the
        // merge leaves a kind-less look, which would fail the whole group's
        // decode below and snap every animated key back to base. Inert
        // instead: no kind, no look; every other key keeps its value. The
        // same for a LUT look whose `media` is not a LUT of the project
        // (GR-8: an end is never checked against the media list).
        if let Some(Value::Object(video)) = state.get_mut("video") {
            video.insert("motion".to_string(), to_json(&base_video.motion));
            if video
                .get("look")
                .is_some_and(|look| !look.is_null() && !self.evaluates_as_look(look))
            {
                video.insert("look".to_string(), Value::Null);
            }
            crate::cutout_check::restore_base_video_keys(video, &base_video);
        }
        // A patch that writes a bad type into a field (12.5 into a tick
        // count, say) loses that whole group rather than failing: the
        // evaluator has no way to report, and a base-props frame is far
        // better than a missing one.
        let decoded_video = state
            .get("video")
            .and_then(|v| serde_json::from_value::<VideoProps>(v.clone()).ok());
        let decoded = decoded_video.is_some();
        let evaluated_video = decoded_video.unwrap_or(base_video);

import AppKit

/// The agent's six action tools — `add_action`, `add_zoom_action`,
/// `add_speed_ramp`, `set_action`, `set_action_end` and `remove_action`: the
/// action rows of
/// spec §6 (and of the op table in the module doc of `core/src/edit.rs`),
/// with the same names and the same argument names.
///
/// A pure move out of `AgentServer+Clips.swift` (issue batch B87 phase 2),
/// which stood over app/CLAUDE.md's ~600-line cap with `set_action_end`'s
/// graphic door to land. The seam is the one the file had already drawn:
/// `// MARK: - Actions` came here whole, with its bodies untouched.
extension AgentServer {

    // MARK: - Actions

    /// `add_action` — ⌥⌘K (`EditorViewController+Inspector`'s
    /// `addActionAtPlayheadCommand`) and the Clip tab's action lane's `+`; and
    /// ⌥-press on the timeline's volume line, which adds a point as an action
    /// (`VolumeLine.point`, spec §11 AU-83).
    /// `at` is CLIP time, not project time: it is measured from the clip's own
    /// start (spec §5.4).
    func addAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let at = try timeArg(a, "at", document)
        let duration = try optionalTimeArg(a, "duration", document)
        return try addedActionResult(
            document, clip, "Add Action",
            [.addAction(clip: clip.id, at: at, duration: duration)])
    }

    /// `add_zoom_action` — the canvas's `Z` rubber band
    /// (`ZoomRegionSession`, `EditorViewController+ZoomRegion.swift`) and the
    /// Clip tab's action lane, whose zoom-in button arms the same mode and
    /// whose zoom-out button ("Zoom Back") sends this with a null region.
    ///
    /// One op rather than `add_action` + `set_action_end` because the
    /// arithmetic that turns a rectangle into a scale and an offset belongs
    /// in the core (`core/src/edit_zoom.rs`'s module doc has the equation),
    /// and because a gesture must be one undo step.
    ///
    /// **`region` is REQUIRED here and optional in the op**, which is the one
    /// place the distinction can be made. The core's envelope reads an absent
    /// optional and an explicit null identically — the crate has no
    /// tri-state argument idiom, which `set_clip` settled in phase 2 — so a
    /// forgotten rectangle would silently become a zoom BACK, the opposite
    /// edit. Requiring the key means a caller says `null` on purpose.
    ///
    /// **The region goes to the core UNREAD** (deepening D1·5,
    /// `archive/roadmap-7.md` §2.5). It is the one op ARGUMENT that
    /// is a caller-authored object, and `edit_zoom.rs`'s `ZoomRegion` reads
    /// it the way a patch is read: an unknown member is named beside the four
    /// the region takes, a missing one is named (there is no defensible
    /// default for any of them), a wrong-typed one is named by its path, and
    /// a four-number LIST is refused rather than read positionally. The
    /// hand reader that used to do all of that member by member is gone with
    /// it.
    func addZoomAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let at = try timeArg(a, "at", document)
        let duration = try optionalTimeArg(a, "duration", document)
        let region = try zoomRegionArg(a, "region")
        let fit = try enumArg(a, "fit", ZoomFit.self)
        let curve = try enumArg(a, "curve", Curve.self)
        // The undo step's NAME is the one thing left that reads the region,
        // and it reads only whether it is a null: a zoom back and a zoom to
        // a rectangle are different edits to a person looking at the Edit
        // menu. What the object CONTAINS is the core's.
        return try addedActionResult(
            document, clip, region is NSNull ? "Zoom Back" : "Zoom to Region",
            [
                .addZoomActionRaw(
                    clip: clip.id, at: at, duration: duration, region: region, fit: fit,
                    curve: curve)
            ])
    }

    /// `add_speed_ramp` — Clip ▸ Speed Ramp… (`SpeedRampSheetController`,
    /// spec §11 SR-24): a speed ramp preset in one step. `from` and `to` are
    /// CLIP time, like `add_action`'s `at`.
    ///
    /// One op rather than `add_action` + `set_action_end` (SR-25), for
    /// `add_zoom_action`'s reasons: the base rate, the overlap and the rate
    /// that fits are the core's reads (D2-1), and a preset is one undo step.
    /// The undo step is named for the shape, as the sheet names it.
    func addSpeedRamp(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let shape = try requiredEnumArg(a, "shape", SpeedRampShape.self)
        guard let rate = try doubleArg(a, "rate") else {
            throw ToolError(message: "Missing required argument: rate")
        }
        let from = try optionalTimeArg(a, "from", document)
        let to = try optionalTimeArg(a, "to", document)
        let curve = try enumArg(a, "curve", Curve.self)
        let hold = try doubleArg(a, "hold")
        return try addedActionResult(
            document, clip, shape.displayName,
            [
                .addSpeedRamp(
                    clip: clip.id, shape: shape, rate: rate, from: from, to: to, curve: curve,
                    hold: hold)
            ])
    }

    /// The tail every action-adding tool shares: run the ops, then report the
    /// action the clip GAINED. Actions are not top-level ids, so
    /// `created(from:to:)` cannot see them, and the new one is the difference
    /// between the clip's action ids before and after.
    private func addedActionResult(
        _ document: ProjectDocument, _ clip: ClipSnapshot, _ actionName: String,
        _ ops: [ReelOp]
    ) throws -> String {
        let before = clip.actions.map { $0.id }
        // The landing is read BEFORE the edit, like `editResult`'s: how a call
        // was addressed is a fact about the CALL, and reading it back off a
        // view the edit could itself have moved would answer about the wrong
        // thing. It matters here for the same reason it matters there — under
        // phase 9's rule the ABSENCE of `scope` in a result means "this landed
        // on the document", so these two tools (`add_action`, `add_zoom_action`)
        // would otherwise report a nested edit as a document one.
        let landing = scopeLanding(ops, document)
        // The captions `add_speed_ramp` re-times ride in the same step
        // (spec §11 SR-27); every other action-adding tool plans nothing.
        let plan = captionRetime(ops, document)
        let snapshot = try performGroupedEdit(
            document, plan.undoName(actionName), ops + plan.ops)
        // Read back through `idScope`, not the top level: inside a scope the
        // clip that just gained an action is one of the nest's, and the
        // timeline's array has never heard of it — which would answer with an
        // empty list and report no new action at all.
        let after = try idScope(document).clip(clip.id)?.actions.map { $0.id } ?? []
        var result: [String: Any] = ["ok": true, "clip": Int(clip.id)]
        let added = after.filter { !before.contains($0) }.map { Int($0) }
        if !added.isEmpty { result["new_actions"] = added }
        result.merge(plan.answerFields) { _, new in new }
        // Empty unless the edit took a clip with sound above the ceiling,
        // which only `add_speed_ramp` of these tools can (SR-21 (e)).
        result.merge(
            SpeedAudioDrop.answerFields(from: snapshot, to: document.project.snapshot)
        ) { _, new in new }
        result.merge(landing) { _, new in new }
        result["project"] = summary(document)
        return try jsonResult(result)
    }

    /// `add_zoom_action`'s `region`, forwarded to the core UNREAD — the
    /// argument half of `rawPatchArg`, and the same one line of judgement
    /// (deepening D1·5).
    ///
    /// It reads NOTHING about the value. The core's `ZoomRegion` is the one
    /// validator of what a region may be, and it answers with the member's
    /// own path (`bad value at "region.width": invalid type: string "wide",
    /// expected f64`), where the hand reader here read the four members one
    /// at a time and had to spell what a region takes itself. An explicit
    /// `NSNull` is forwarded as it was written: the op reads a `null` as
    /// absent and both mean a zoom BACK.
    ///
    /// **The ABSENT key is the one thing left**, and unlike `rawPatchArg`'s
    /// it is not merely a mistake about the call — it is the distinction the
    /// core cannot make. An absent optional and an explicit null are one
    /// thing to the envelope, so a forgotten rectangle would be a zoom back
    /// rather than an error; the handler above says why the tool draws a
    /// line the op does not.
    private func zoomRegionArg(_ a: [String: Any], _ key: String) throws -> Any {
        guard let raw = a[key] else {
            throw ToolError(
                message: "Missing required argument: \(key) — the rectangle to zoom to, as "
                    + "{x, y, width, height} in SOURCE pixels, where x and y are its CENTRE "
                    + "measured from the centre of the clip's cropped rect. Pass null to zoom "
                    + "BACK to the clip's own scale and position.")
        }
        return raw
    }

    /// `set_action` — the Clip tab's action lane: the selected action's
    /// Start, Length and Curve in its detail row, and dragging a band's body
    /// (move) or its outer 5 pt (resize) in that lane or on the timeline's
    ///
    /// **The patch goes to the core UNREAD** (deepening D1·5,
    /// `archive/roadmap-7.md` §2.5) — the LAST door of the six, and
    /// the one that used to check the most: `checkActionPatch` walked three
    /// allowed-key sets, `checkVideoEnums` and `checkTextEnums` ran here
    /// alone, and `patchArg`'s round trip decoded the whole thing through
    /// `ActionPatch`. The core walks it group by group now
    /// (`edit_action.rs`'s `check_end_patch` over `patch.rs`), so every
    /// refusal carries the group in its path — `unknown key
    /// "video.filters[1].kindd" in an action end patch` — and three things
    /// that used to LAND do not: a wrong-typed value one level down (a
    /// number where `shadow` belongs read as "clear the shadow"), a
    /// three-element colour (`withOpaqueColors` filled in the alpha), and a
    /// one-key nested object, which REPLACED what the end state held and now
    /// merges into it.
    ///
    /// Two refusals are still made away from `patch.rs` and both are about
    /// this OP: `video.motion` and `text.words` are not animation targets
    /// (`edit_action.rs`), and an empty patch is the core's identity answer
    /// rather than this side's "nothing to change".
    ///
    /// **`schema` is the app's to fill** (spec §11 G-34 (c), G-4). When the
    /// patch names `graphic` and the clip — found in the call's scope, so a
    /// nest's clip is the nest's — is a graphic clip, `graphicEndSchema`
    /// sends the CURRENT revision's schema of the module it is drawn by, read
    /// as `set_graphic` reads it. Otherwise none goes, and the core answers:
    /// `clip N is not a graphic clip` for any other clip (asked before the
    /// schema), and for a value whose module is missing or does not compile,
    /// `graphic.props.<key> needs its module's schema to animate, and none
    /// came with the op` — while a `null` still removes, so a stale key can
    /// leave an end whose module is broken. Nothing here writes a sentence of
    /// its own.
    func setActionEnd(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let action = try actionArg(a, "action", clip)
        let patch = try rawPatchArg(a, "patch")
        // `off` (CI-14) is the caller's own choice; its refusals are the core's.
        let off = try stringsArg(a, "off") ?? []
        let schema = graphicEndSchema(patch, clip, document)
        return try retimingEditResult(
            document, "Action End",
            [
                .setActionEndRaw(
                    clip: clip.id, action: action.id, patch: patch,
                    off: off, schema: schema)
            ])
    }

    /// The schema `set_action_end` sends with a graphic end patch: the
    /// CURRENT revision's, of the module `clip` is drawn by, read through
    /// `compiledModule` as `setGraphic` reads it — or nil when the patch
    /// names no `graphic` (any value, a `null` included), the clip is not a
    /// graphic, or the module is missing or does not compile. It never
    /// throws and reads nothing of the patch beyond the key's presence: what
    /// a missing schema means is the core's sentence to say (D2-1).
    func graphicEndSchema(
        _ patch: Any, _ clip: ClipSnapshot, _ document: ProjectDocument
    ) -> [String: Any]? {
        guard let fields = patch as? [String: Any], fields["graphic"] != nil,
            let name = clip.graphic?.name
        else { return nil }
        return try? compiledModule(named: name, document).schema
    }

    /// `remove_action` — the action lane's trash button, and ⌫ with an
    /// action selected.
    func removeAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let action = try actionArg(a, "action", clip)
        return try retimingEditResult(
            document, "Remove Action", [.removeAction(clip: clip.id, action: action.id)])
    }

