66	    /// The latest clip END that fits: the clip's start plus S⁻¹ of what the
67	    /// file holds past `in`, snapped DOWN onto the grid, never before the
68	    /// start.
69	    fn latest_fitting_end(&self, clip: &Clip) -> Ticks {
70	        let Some((source_in, file)) = self.window_of(clip) else {
71	            return clip.start;
72	        };
73	        let remaining = file.saturating_sub(source_in).max(0) as f64;
