75	            Some(map) => map.time_at(remaining),
76	            None if clip.speed.is_finite() && clip.speed > 0.0 => {
77	                let t = (remaining / clip.speed).floor();
78	                if t.is_finite() {
79	                    t as Ticks
80	                } else {
81	                    0
82	                }
83	            }
84	            None => remaining as Ticks,
85	        };
