90	    /// The largest end rate on the 0.001 grid, below `rate`, at which
91	    /// action `action` of `after` reads inside its file: R1's solve, then
92	    /// its step down. `None` when none down to ×0.1 does. Read by R1 and by
93	    /// a split's second half (spec §11 SR-18 (e)).
94	    pub(crate) fn largest_fitting_end_rate(
95	        &self,
96	        after: &Clip,
97	        action: u32,
98	        rate: f64,
99	    ) -> Option<f64> {
100	        let floor = (SPEED_MIN * 1000.0).round() as i64;
101	        self.largest_fitting_rate(&|x| ending_at(after, action, x), rate, floor)
102	    }
