282	/// Reads `body`, the patch's `graphic` value, for `clip` against `schema`.
283	/// `Err` in the dotted path's own sentence for a body or `props` that is not
284	/// an object, a layer key, an unknown key, and for each non-null prop, in
285	/// this order: a clip that is not a graphic, no schema, a prop the schema
286	/// lacks, a prop marked `animate: false` (G-41), and whatever `check_typed`
287	/// refuses.
288	pub(crate) fn read_graphic_end(
289	    clip: &Clip,
290	    body: &Value,
291	    schema: Option<&Value>,
292	) -> Result<GraphicEnd, String> {
293	    let mut read = GraphicEnd {
294	        remove: false,
295	        props: Map::new(),
296	        kinds: Map::new(),
297	        starts: Map::new(),
298	    };
299	    let fields = match body {
300	        Value::Null => {
301	            read.remove = true;
302	            return Ok(read);
303	        }
304	        Value::Object(fields) => fields,
305	        other => {
306	            return Err(format!(
307	                "graphic in an action end patch must be a json object, not {}",
308	                describe(other)
309	            ))
310	        }
311	    };
312	    let mut props = None;
313	    for (key, value) in fields {
314	        match key.as_str() {
315	            "props" => props = Some(value),
316	            // Rewritten from the schema for every named prop (G-34 (a)).
317	            "kinds" => {}
318	            layer if LAYER_KEYS.contains(&layer) => {
319	                return Err(format!(
320	                    "graphic.{layer} is not an animation target; an action animates graphic.props"
321	                ))
322	            }
323	            other => return Err(unknown_key(&format!("graphic.{other}"), END_PATCH)),
324	        }
325	    }
326	    let props = match props {
327	        None => return Ok(read),
328	        Some(Value::Null) => {
329	            read.remove = true;
330	            return Ok(read);
331	        }
332	        Some(Value::Object(props)) => props,
333	        Some(other) => {
334	            return Err(format!(
335	                "graphic.props must be a json object, not {}",
336	                describe(other)
337	            ))
338	        }
339	    };
340	    for (key, value) in props {
341	        // A removal is never checked, so a stale key can go (G-34 (j)).
342	        if value.is_null() {
343	            read.props.insert(key.clone(), Value::Null);
344	            continue;
345	        }
346	        let stored = clip
347	            .graphic
348	            .as_ref()
349	            .filter(|_| matches!(clip.source, Source::Graphic))
350	            .ok_or_else(|| format!("clip {} is not a graphic clip", clip.id))?;
351	        let schema = schema.ok_or_else(|| {
352	            format!(
353	                "graphic.props.{key} needs its module's schema to animate, and none came with the op"
354	            )
355	        })?;
356	        let entry = schema
357	            .get(key)
358	            .ok_or_else(|| unknown_key(&format!("graphic.props.{key}"), END_PATCH))?;
359	        if entry.get("animate") == Some(&Value::Bool(false)) {
360	            return Err(format!(
361	                "graphic.props.{key} is marked animate: false by its module; an action does not \
362	                 animate it — set it with set_graphic"
363	            ));
364	        }
365	        let kind = entry.get("type").and_then(Value::as_str).unwrap_or("");
366	        let value = check_typed(key, entry, value).map_err(|why| format!("graphic.{why}"))?;
367	        read.props.insert(key.clone(), value);
368	        read.kinds
369	            .insert(key.clone(), Value::String(kind.to_string()));
370	        if !stored.props.contains_key(key) {
371	            if let Some(default) = schema_default(schema, key) {
372	                read.starts.insert(key.clone(), default);
373	            }
374	        }
375	    }
376	    Ok(read)
377	}
