551	/// One prop from `from` toward `to` by eased progress `u`.
552	///
553	/// The two switch points come first, as in `actions.rs`'s `lerp_at`: at
554	/// `u <= 0` the start as stored, so an integer start stays an integer and
555	/// the layer's hash at an action's first tick is the hash before it; at
556	/// `u >= 1` the end as stored.
557	fn lerp_prop(from: &Value, to: &Value, colour: bool, u: f64) -> Value {
558	    if u <= 0.0 {
559	        return from.clone();
560	    }
561	    if u >= 1.0 {
562	        return to.clone();
563	    }
564	    match (from, to) {
565	        (Value::Number(a), Value::Number(b)) => match (a.as_f64(), b.as_f64()) {
566	            // Never rounded, even when both ends are whole (G-34 (e));
567	            // `from_f64` refuses a non-finite result, which holds instead.
568	            (Some(a), Some(b)) => Number::from_f64(a + (b - a) * u)
569	                .map(Value::Number)
570	                .unwrap_or_else(|| from.clone()),
571	            _ => from.clone(),
572	        },
573	        (Value::String(a), Value::String(b)) if colour => {
574	            match (color_channels(a), color_channels(b)) {
575	                (Some(a), Some(b)) => Value::String(color_hex(oklab_mix(a, b, u))),
576	                _ => from.clone(),
577	            }
578	        }
579	        _ => from.clone(),
580	    }
581	}
