682	/// Every four-channel colour an action's state holds, by key (spec §11 G-43).
683	pub(crate) const COLOR_POINTERS: [&str; 8] = [
684	    "/video/shadow/color",
685	    "/text/color",
686	    "/text/outline/color",
687	    "/text/backdrop/color",
688	    "/text/word_style/active_color",
689	    "/text/word_style/spoken_color",
690	    "/text/word_style/upcoming_color",
