697	/// Overwrites each colour in `out` (the lerped state) with the OKLab blend of `from`'s and
698	/// `to`'s values at the same pointer, by eased progress `u`.
699	pub(crate) fn blend_colors(from: &Value, to: &Value, u: f64, out: &mut Value) {
700	    let inside = u > 0.0 && u < 1.0;
701	    if !inside {
702	        return;
703	    }
704	    for pointer in COLOR_POINTERS {
705	        if let Some((a, b)) = ends::<4>(from, to, pointer) {
706	            write(out, pointer, &oklab_mix_unit(a, b, u));
707	        }
708	    }
709	    if let Some((a, b)) = ends::<3>(from, to, CHROMA_KEY_POINTER) {
710	        write(out, CHROMA_KEY_POINTER, &oklab_mix_rgb(a, b, u));
711	    }
712	}
