715	/// either does not read as one or they are the same numbers (compared
716	/// parsed, so a stored `1.0` and an end's `1` are one colour).
717	fn ends<const N: usize>(from: &Value, to: &Value, pointer: &str) -> Option<([f64; N], [f64; N])> {
718	    let a = channels::<N>(from.pointer(pointer)?)?;
719	    let b = channels::<N>(to.pointer(pointer)?)?;
720	    (a != b).then_some((a, b))
721	}
