723	/// An array of exactly `N` numbers.
724	fn channels<const N: usize>(value: &Value) -> Option<[f64; N]> {
725	    let list = value.as_array()?;
726	    if list.len() != N {
727	        return None;
728	    }
729	    let mut out = [0.0; N];
730	    for (slot, element) in out.iter_mut().zip(list) {
731	        *slot = element.as_f64()?;
732	    }
733	    Some(out)
734	}
