736	/// Writes `channels` as floats at `pointer`, when `out` has a value there
737	/// and every channel is finite.
738	fn write(out: &mut Value, pointer: &str, channels: &[f64]) {
739	    let Some(numbers) = channels
740	        .iter()
741	        .map(|&v| Number::from_f64(v).map(Value::Number))
742	        .collect::<Option<Vec<Value>>>()
743	    else {
744	        return;
745	    };
746	    if let Some(slot) = out.pointer_mut(pointer) {
747	        *slot = Value::Array(numbers);
748	    }
749	}
