267	/// The graphic's LAYER keys: real keys of `graphic`, and not an action's.
268	const LAYER_KEYS: [&str; 5] = ["name", "width", "height", "in", "length"];
269	
270	/// A patch's `graphic` body, read and checked.
271	pub(crate) struct GraphicEnd {
272	    /// `graphic: null` or `graphic.props: null`: drop the group.
273	    pub(crate) remove: bool,
274	    /// Each named prop, checked and normalised; `Null` means removal.
275	    pub(crate) props: Map<String, Value>,
276	    /// A `Value::String(type)` per non-null prop, from the schema.
277	    pub(crate) kinds: Map<String, Value>,
278	    /// The schema's default for each non-null prop the clip's map lacks.
279	    pub(crate) starts: Map<String, Value>,
280	}
