379	/// Writes a read `graphic` body into `end`, an object after the generic
380	/// merge. A group or slot that is not an object is replaced by `{}` only
381	/// when a value is to be written into it; a removal creates nothing.
382	pub(crate) fn write_graphic_end(end: &mut Value, read: &GraphicEnd) {
383	    let Value::Object(groups) = end else {
384	        return;
385	    };
386	    if read.remove {
387	        groups.shift_remove("graphic");
388	        return;
389	    }
390	    if read.props.values().any(|value| !value.is_null()) {
391	        let graphic = groups
392	            .entry("graphic")
393	            .or_insert_with(|| Value::Object(Map::new()));
394	        if !graphic.is_object() {
395	            *graphic = Value::Object(Map::new());
396	        }
397	        if let Value::Object(graphic) = graphic {
398	            // `props` before `kinds`, the stored order.
399	            for slot in ["props", "kinds"] {
400	                let slot = graphic
401	                    .entry(slot)
402	                    .or_insert_with(|| Value::Object(Map::new()));
403	                if !slot.is_object() {
404	                    *slot = Value::Object(Map::new());
405	                }
406	            }
407	        }
408	    }
409	    let Some(Value::Object(graphic)) = groups.get_mut("graphic") else {
410	        return;
411	    };
412	    for (key, value) in &read.props {
413	        if value.is_null() {
414	            for slot in ["props", "kinds"] {
415	                if let Some(Value::Object(map)) = graphic.get_mut(slot) {
416	                    map.shift_remove(key);
417	                }
418	            }
419	            continue;
420	        }
421	        if let Some(Value::Object(map)) = graphic.get_mut("props") {
422	            map.insert(key.clone(), value.clone());
423	        }
424	        if let (Some(kind), Some(Value::Object(map))) =
425	            (read.kinds.get(key), graphic.get_mut("kinds"))
426	        {
427	            map.insert(key.clone(), kind.clone());
428	        }
429	    }
430	}
