432	/// The schema entry's default for `key`, a `color` normalised (G-12), an
433	/// `asset`'s `null` answered as `""` (G-42); `None` for no entry or no
434	/// default.
435	pub(crate) fn schema_default(schema: &Value, key: &str) -> Option<Value> {
436	    let entry = schema.get(key)?;
437	    let default = entry.get("default")?;
438	    match entry.get("type").and_then(Value::as_str) {
439	        // "No image" in an end is `""`, since a `null` there removes (G-42).
440	        Some("asset") if default.is_null() => Some(Value::String(String::new())),
441	        Some("color") => default
442	            .as_str()
443	            .and_then(normalise_color)
444	            .map(Value::String),
445	        _ => Some(default.clone()),
446	    }
447	}
448	//! A graphic clip's props at a clip time (format version 13, spec §11
449	//! G-34): the fourth thing an action animates, beside `actions.rs`'s three
450	//! groups and outside its `merge` / `lerp`, because a prop's kind is not
451	//! the value's shape and a whole number is not a tick count.
452	//!
453	//! The rule is §5.4's, applied to `graphic.props` alone. Each FINISHED
454	//! action's `end.graphic.props` is laid over the clip's own map in start
455	//! order, by `insert` (`model_graphic.rs`'s rule, so a stored key keeps its
456	//! slot and an action's new key goes after the stored ones). Then the
457	//! action that SPANS the time moves each prop it names from the value
458	//! reached so far toward its end along its curve:
459	//!
460	//! - **a number** in floating point, `a + (b − a) × eased`, never rounded
461	//!   and never snapped to a `step` (G-34 (e)) — so two whole ends 64 and
462	//!   129 give 96.5 halfway, and a module that wants a whole number rounds;
463	//! - **a colour**, known by `end.graphic.kinds.<key> == "color"` and never
464	//!   by the value's shape, in OKLab through `model_color.rs`'s
465	//!   `color_channels`, `oklab_mix` and `color_hex` — stdlib's
466	//!   `interpolateColors`' blend, byte for byte, with STRAIGHT alpha, each
467	//!   channel rounded to the nearest byte (G-40, amending G-34 (f)). The
468	//!   model's own `[r, g, b, a]` colours blend through `actions_color.rs`
469	//!   with the same arithmetic, in floating point (G-43);
470	//! - **anything else** — a string, a boolean, an enum, an asset (G-42), two values of
471	//!   different JSON kinds, a colour it cannot read — holds its start and
472	//!   takes the end's value at the action's END.
473	//!
474	//! **Total.** A malformed `graphic`, `props` or `kinds` reads as "names
475	//! nothing" and a prop with no start stays absent until its action ends, so
476	//! no frame fails: a file is stored as found and nothing here unwraps.
477	
478	use serde_json::{Map, Number, Value};
479	
480	use crate::actions::{ease, ordered_actions, spans};
481	use crate::model::{Clip, GraphicProps};
482	use crate::model_color::{color_channels, color_hex, oklab_mix};
483	use crate::time::Ticks;
484	
485	/// The clip's `graphic` with its `props` evaluated at `clip_t`, its other
486	/// fields as stored; `None` when the clip has no graphic.
487	pub(crate) fn evaluate_graphic(clip: &Clip, clip_t: Ticks) -> Option<GraphicProps> {
488	    let mut graphic = clip.graphic.clone()?;
489	    if clip.actions.is_empty() {
490	        return Some(graphic);
491	    }
492	    let actions = ordered_actions(clip);
493	    for action in &actions {
494	        let end = action.start.saturating_add(action.duration);
495	        if action.duration > 0 && end <= clip_t {
496	            for (key, value) in end_props(&action.end).into_iter().flatten() {
497	                if !value.is_null() {
498	                    graphic.props.insert(key.clone(), value.clone());
499	                }
500	            }
501	        }
502	    }
503	    if let Some(action) = actions.iter().find(|a| spans(a, clip_t)) {
504	        let elapsed = clip_t.saturating_sub(action.start) as f64;
505	        let u = ease(action.curve, elapsed / action.duration as f64);
506	        for (key, to) in end_props(&action.end).into_iter().flatten() {
507	            if to.is_null() {
508	                continue;
509	            }
510	            // A prop with no start has nothing to move from: it stays
511	            // absent until the action ends, then the loop above lays it in.
512	            let Some(from) = graphic.props.get(key) else {
513	                continue;
514	            };
515	            let value = lerp_prop(from, to, is_colour(&action.end, key), u);
516	            graphic.props.insert(key.clone(), value);
517	        }
518	    }
519	    Some(graphic)
520	}
