522	/// True when some action on the clip names `key` in its end's
523	/// `graphic.props` with a value that is not `null` — the question
524	/// `set_graphic`'s `null` and `paste_attributes`' kept key both ask
525	/// (G-34 (d)).
526	pub(crate) fn names_prop(clip: &Clip, key: &str) -> bool {
527	    clip.actions.iter().any(|action| {
528	        end_props(&action.end)
529	            .and_then(|props| props.get(key))
530	            .is_some_and(|value| !value.is_null())
531	    })
532	}
