534	/// An end's `graphic.props`, or `None` when the end, its `graphic` or its
535	/// `props` is not an object.
536	fn end_props(end: &Value) -> Option<&Map<String, Value>> {
537	    end.get("graphic")?.get("props")?.as_object()
538	}
