540	/// The end records `key`'s kind as `color`. Anything else — no `kinds`, a
541	/// `kinds` that is not an object, another kind — is not a colour, so a
542	/// file written before `kinds` existed switches its colours at the end.
543	fn is_colour(end: &Value, key: &str) -> bool {
544	    end.get("graphic")
545	        .and_then(|graphic| graphic.get("kinds"))
546	        .and_then(|kinds| kinds.get(key))
547	        .and_then(Value::as_str)
548	        == Some("color")
