348	        let capped = |want: Ticks, handle: Option<Ticks>| handle.map_or(want, |h| want.min(h));
349	        let mut b = capped(want_b, head_frames);
350	        let mut a = capped(want_a, tail_frames);
351	        if align == TransitionAlign::Center {
352	            let short = (want_b - b) + (want_a - a);
353	            if short > 0 {
354	                let room_b = head_frames.map_or(short, |h| (h - b).max(0));
355	                let moved = short.min(room_b);
356	                b += moved;
357	                let room_a = tail_frames.map_or(short - moved, |h| (h - a).max(0));
358	                a += (short - moved).min(room_a);
359	            }
360	        }
361	
362	        // 5. The neighbours. A may not reach B's successor, and B may not
363	        //    reach A's predecessor. Both are closed form.
364	        if let Some(next_clip) = ordered.get(index + 1) {
365	            let room = frames_between(clip_end(&earlier), next_clip.start, fps).max(0);
366	            a = a.min(room);
367	        }
368	        if let Some(before) = index.checked_sub(2).and_then(|i| ordered.get(i)) {
369	            let room = frames_between(clip_end(before), later.start, fps).max(0);
370	            b = b.min(room);
371	        }
372	
373	        // 6 and 7. The same larger-side reduction path, searched by total.
374	        //    Each extension is whole GRID frames stepped from an inward base
375	        //    — A's end snapped down, B's start snapped up — never `count ×`
376	        //    a frame: at a canvas rate whose frame is not a whole number of
377	        //    ticks (7 fps, or 5994/100 as a file sometimes spells 59.94) a
378	        //    multiple of it is not a grid position, and the model never
379	        //    holds a sub-frame start (`time.rs`). For a position ON the grid
380	        //    at a rate that divides the timescale they are exactly
381	        //    `a × frame` and `b × frame`. For one that is not, the first
382	        //    frame is partly spent landing the edge on the grid, which is
383	        //    `time::snap_up_to_frame`'s own argument for a BOUND.
384	        let a_end = clip_end(&earlier);
385	        let (tail_base, head_base) = (self.snapped_down(a_end), self.snapped_up(later.start));
386	        let extension = |a: Ticks, b: Ticks| {
387	            let tail = frames_back(tail_base, a.saturating_neg(), fps)
388	                .saturating_sub(a_end)
389	                .max(0);
390	            let head = later
391	                .start
392	                .saturating_sub(frames_back(head_base, b, fps))
393	                .max(0);
394	            (tail, head)
395	        };
396	        let total = a + b;
397	        let winner = largest_passing(total, |remaining| {
398	            let (a, b) = reduced_split(a, b, remaining);
399	            let (tail, head) = extension(a, b);
400	            if tail + head <= 0 {
401	                return true;
402	            }
403	            let (grown, moved) = extended(&earlier, &later, tail, head);
404	            self.check_overlap_rule(&[grown, moved], later.track, &[])
405	                .is_ok()
406	        });
407	        let (a, b) = reduced_split(a, b, winner);
408	        let (tail, head) = extension(a, b);
409	        if tail + head <= 0 {
410	            // Three clamps can land here — the two handles, the
411	            // neighbours on the track, and the search above — so the
412	            // sentence names all three rather than guessing which one
413	            // it was. The number in it is the request in whole FRAMES of
414	            // the canvas's grid (`time::frames_in`), the unit a caller
415	            // has to change.
416	            return Ok(Outcome::Refused(format!(
417	                "the cut before clip {clip} has no room for an overlap: the {requested} \
418	                     frames asked for clamp to nothing against the two clips' unused \
419	                     material, their neighbours and the overlap rule; pass ripple: true to \
420	                     make the overlap by shifting the timeline left instead"
421	            )));
422	        }
423	
424	        // 8, 9 and 10. Write.
425	        let (grown, mut moved) = extended(&earlier, &later, tail, head);
426	        for action in &mut moved.actions {
427	            action.start = action.start.saturating_add(head);
428	        }
429	        if let Some(text) = moved.text.as_mut() {
430	            rebase_words(text, head.saturating_neg());
431	        }
432	        moved.transition_in = Some(match (kind, later.transition_in) {
433	            (Some(kind), Some(stored)) => Transition { kind, ..stored },
434	            (Some(kind), None) => Transition::minted(kind),
435	            (None, Some(stored)) => stored,
436	            (None, None) => Transition::minted(TransitionKind::default()),
437	        });
438	
439	        let mut next = self.clone();
440	        if let Some(slot) = next.clip_mut(earlier.id) {
441	            *slot = grown;
442	        }
443	        if let Some(slot) = next.clip_mut(clip) {
444	            *slot = moved;
445	        }
446	        self.finish(next)
447	    }
448	
449	    /// How many whole frames the INCOMING clip could be extended backward
450	    /// by, or `None` for a source with no window at all. See
451	    /// [`Project::add_transition`] step 2 for why a nest answers `Some(0)`.
452	    fn head_handle_frames(&self, clip: &Clip) -> Option<Ticks> {
453	        // The earliest start the handle allows, snapped INWARD, so the
454	        // count is whole frames of material that is really there even when
455	        // the clip's own start is not on the grid — `source_window.rs`'s
456	        // one spelling of it (spec §11, D4-5), which reads an unmeasurable
457	        // head as EMPTY rather than as unbounded, as this op needs.
458	        let earliest = match clip.source {
459	            Source::Nest { .. } => self.snapped_up(clip.start),
460	            _ => self.earliest_start_on_grid(clip)?,
461	        };
462	        Some(frames_between(earliest, clip.start, self.canvas.fps).max(0))
463	    }
464	
465	    /// How many whole frames the OUTGOING clip could be extended forward
466	    /// by, or `None` for a source with no window at all.
467	    fn tail_handle_frames(&self, clip: &Clip) -> Option<Ticks> {
468	        let tail = match clip.source {
469	            Source::Nest { project, .. } => self
470	                .nest(project)
471	                .map_or(0, |nest| nest.duration().saturating_sub(clip.duration))
472	                .max(0),
473	            // No measurable window is no tail, not an unbounded one.
474	            _ => self
475	                .source_length_on_timeline(clip)
476	                .or_empty()?
477	                .saturating_sub(clip.duration)
478	                .max(0),
479	        };
480	        let end = clip_end(clip);
481	        let latest = self.snapped_down(end.saturating_add(tail));
482	        Some(frames_between(end, latest, self.canvas.fps).max(0))
483	    }
484	
485	    /// Moves the clip so its overlap with its predecessor is exactly
486	    /// `duration` (spec §6) — the transition's length IS that overlap, so
487	    /// there is nothing else to set.
488	    ///
489	    /// Refuses when the clip has no predecessor on its track, when the
490	    /// duration is past the pair's overlap limit (half the shorter clip,
491	    /// snapped down) — which covers a start below 0 and a start in front of
492	    /// the predecessor (#175) — or when the result breaks the overlap rule
493	    /// elsewhere; each sentence names the value (spec §11 #88). `Err` on a
494	    /// negative duration.
495	    pub fn set_transition_duration(&self, clip: u32, duration: Ticks) -> Result<Outcome, String> {
496	        let target = self.require_clip(clip)?.clone();
497	        let duration = self.snapped(duration);
498	        if duration < 0 {
499	            return Err(format!(
500	                "transition duration must not be negative, not {duration}"
501	            ));
502	        }
503	        let ordered = self.clips_on_track(target.track);
504	        let index = match ordered.iter().position(|c| c.id == clip) {
505	            Some(index) => index,
506	            None => return Ok(Outcome::Identity),
507	        };
508	        let Some(previous) = index.checked_sub(1).and_then(|i| ordered.get(i)) else {
509	            return Ok(Outcome::Refused(format!(
510	                "clip {clip} is the first clip on track {}, so there is no clip before it \
511	                 to overlap",
512	                target.track
513	            )));
514	        };
515	        // The overlap is the tail of the previous clip the later one covers,
516	        // so the later one starts exactly `duration` before that tail ends.
517	        let start = clip_end(previous).saturating_sub(duration);
518	        let limit = self.snapped_down(overlap_limit(previous, &target));
519	        if duration > limit {
520	            let place = if start < 0 {
521	                ", before the timeline,".to_string()
522	            } else if start < previous.start {
523	                format!(
524	                    ", before clip {} starts at {},",
525	                    previous.id, previous.start
526	                )
527	            } else {
528	                String::new()
529	            };
530	            return Ok(Outcome::Refused(format!(
531	                "clip {clip} would start at {start}{place} to overlap clip {} by {duration} \
532	                 ticks; the two can overlap by at most {limit} ticks",
533	                previous.id
534	            )));
535	        }
536	
537	        let mut moved = target.clone();
538	        moved.start = start;
539	        self.commit_replacements(vec![moved])
540	    }
