542	//! The `ripple` half of `add_transition` — the overlap made by SHIFTING
543	//! rather than out of the two clips' handles.
544	//!
545	//! Cut out of `edit_transition.rs` under the size rule, a pure move. It
546	//! sits in its own file rather than beside the handle form because the two
547	//! answer the same question out of different material: the handle form
548	//! spends unused source and moves nothing, while this one spends the
549	//! TIMELINE and moves every clip at or after the cut, which is
550	//! `close_gap`'s set and `close_gap`'s rules. `add_transition` reads the
551	//! arguments, finds the cut and hands over here (spec §11, R5-3's
552	//! amendment of 2026-09-16); nothing else calls it.
553	
554	use crate::edit_time::{locked_track, shift_clips, shifted, unlocked_tracks};
555	use crate::edit_transition::transition_too_short;
556	use crate::model::{Clip, Project, Transition, TransitionKind};
557	use crate::outcome::Outcome;
558	use crate::time::{frames_back, frames_in, frames_within, snap_up_to_frame, Ticks};
559	use crate::transition_search::shift_frame_limit;
560	
561	impl Project {
562	    pub(crate) fn add_transition_by_shift(
563	        &self,
564	        earlier: &Clip,
565	        later: &Clip,
566	        kind: Option<TransitionKind>,
567	        duration: Ticks,
568	    ) -> Result<Outcome, String> {
569	        let unlocked = unlocked_tracks(self);
570	        if !unlocked.contains(&later.track) {
571	            return Ok(Outcome::Refused(locked_track(
572	                later.track,
573	                &format!(
574	                    "clip {} cannot be shifted left to make the overlap",
575	                    later.id
576	                ),
577	            )));
578	        }
579	        let fps = self.canvas.fps;
580	        let asked = frames_in(duration, fps);
581	        if asked < 1 {
582	            let one = snap_up_to_frame(1, fps);
583	            return Ok(Outcome::Refused(transition_too_short(
584	                later.id, duration, one,
585	            )));
586	        }
587	        let cut = later.start;
588	        // `shift_clips`'s own set, linked partners included (spec §11 AU-91).
589	        let mut touched: Vec<u32> = Vec::new();
590	        for clip in shifted(self, cut).iter().filter_map(|id| self.clip(*id)) {
591	            if !touched.contains(&clip.track) {
592	                touched.push(clip.track);
593	            }
594	        }
595	
596	        let shorter = earlier.duration.min(later.duration);
597	        // The pair rule is in ticks; how many grid frames back from the cut
598	        // fit inside it is the count the shift may spend.
599	        let allowed = frames_within(cut, shorter / 2, fps);
600	        let frames = asked.min(allowed);
601	        if frames <= 0 {
602	            return Ok(Outcome::Refused(format!(
603	                "clips {} and {} have no room to overlap by shifting: the overlap asked \
604	                 for is {asked} frames and half of the shorter clip is {allowed} frames",
605	                earlier.id, later.id
606	            )));
607	        }
608	        let most = frames;
609	        for track in &touched {
610	            if let Err(why) = self.check_overlap_rule(&[], *track, &[]) {
611	                return Ok(Outcome::Refused(why));
612	            }
613	        }
614	        if let Some(frames) = shift_frame_limit(self, cut, most, &touched) {
615	            let mut next = self.clone();
616	            let delta = frames_back(cut, frames, fps).saturating_sub(cut);
617	            if let Some(why) = shift_clips(&mut next, cut, delta) {
618	                return Ok(Outcome::Refused(why));
619	            }
620	            for track in &touched {
621	                if let Err(why) = next.check_overlap_rule(&[], *track, &[]) {
622	                    return Ok(Outcome::Refused(why));
623	                }
624	            }
625	            if let Some(slot) = next.clip_mut(later.id) {
626	                slot.transition_in = Some(match (kind, later.transition_in) {
627	                    (Some(kind), Some(stored)) => Transition { kind, ..stored },
628	                    (Some(kind), None) => Transition::minted(kind),
629	                    (None, Some(stored)) => stored,
630	                    (None, None) => Transition::minted(TransitionKind::default()),
631	                });
632	            }
633	            return self.finish_placement(next, &touched);
634	        }
635	        Ok(Outcome::Refused(format!(
636	            "clips {} and {} cannot overlap by shifting: no overlap from {most} frames down \
637	             to one leaves every track the shift moves inside the overlap rule",
638	            earlier.id, later.id
639	        )))
640	    }
